INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-A-006', 'L', 'lan', 'A', '{"kind":"ANN","audio":"audio/L/ANN-006.mp3","test":"T1","qs":[{"stem":"What is the announcement mainly about?","opts":["Changes at a campus café","A new building for the science department","A food festival on Wednesday","Job openings at the café"]},{"stem":"When will the café close early?","opts":["On Monday afternoons","On Wednesdays at noon","On Tuesday evenings","On Fridays at three"]}]}', '[0,1]', '["B, C, D — не упоминаются","*close at noon on Wednesdays for staff training*. A, C — скидки на напитки; D — не сказано","Welcome back, students. The Green Leaf Café in the science building has a new menu this semester. Everything is now made with locally grown ingredients, and there are more vegetarian options than before. To celebrate, all drinks will be half price this Monday and Tuesday. The café is open from eight a.m. to three p.m., but it will close at noon on Wednesdays for staff training."]', '["Main Idea","Factual"]', -1, 'pretest', 1793553157228, 1793553157228)
