INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-A-010', 'L', 'lan', 'A', '{"kind":"ANN","audio":"audio/L/ANN-010.mp3","test":"T2","qs":[{"stem":"What is the announcement mainly about?","opts":["A sale at the campus bookstore","New store hours","A new university logo","A pen design contest"]},{"stem":"When does the sale end?","opts":["Friday morning","Thursday afternoon","Saturday evening","Sunday night"]}]}', '[0,2]', '["*The campus bookstore is having a big sale*. B — не упоминается; C — логотип только на толстовках; D — не упоминается","*ends on Saturday at six p.m.* A — не то время; B — не то время; D — не то время","Hello, students. The campus bookstore is having a big sale this week. All notebooks and pens are thirty percent off. Sweatshirts with the university logo are fifty percent off. The sale ends on Saturday at six p.m. Remember to bring your student ID to get the discount."]', '["Main Idea","Factual"]', -1, 'pretest', 1793553157228, 1793553157228)
