INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-A-015', 'L', 'lan', 'A', '{"kind":"ANN","audio":"audio/L/ANN-015.mp3","test":"T3","qs":[{"stem":"What is the announcement mainly about?","opts":["A cleanup day on campus","A change in dining hall hours","New classroom buildings","A new recycling program"]},{"stem":"Where should students put food and napkins?","opts":["In the gray bins","In the blue bins","In the dining hall office","In the recycling center"]}]}', '[3,0]', '["*The campus recycling program is starting*. A — день уборки не упоминается; B — часы столовой не обсуждаются; C — здания уже есть","*Food and napkins should go in the gray bins*. B — синие — бумага, пластик, банки; C — не упоминается; D — не упоминается","Hello, students. The campus recycling program is starting this week. There will be new blue bins near every classroom building and in the dining hall. Please put paper, plastic bottles, and cans in the blue bins. Food and napkins should go in the gray bins. The bins will be emptied every morning. Thank you for helping keep our campus clean."]', '["Main Idea","Factual"]', -1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-A-017', 'L', 'lan', 'A', '{"kind":"ANN","audio":"audio/L/ANN-017.mp3","test":null,"qs":[{"stem":"What is the announcement mainly about?","opts":["New library hours","A new library building","A library book sale","A change in student ID rules"]},{"stem":"How can students reserve the quiet study rooms?","opts":["At the front desk","By calling the guards","Online","On the third floor"]}]}', '[0,2]', '["*the library will be open until midnight*. B — здание то же; C — не упоминается; D — ID уже нужен","*can be reserved online*. A — не упоминается; B — охрана проверяет ID; D — комнаты на 3-м этаже","Attention, students. Starting next week, the library will be open until midnight on weekdays. On Saturdays, it will open at nine in the morning and close at six. The quiet study rooms on the third floor can be reserved online. Please bring your student ID, because the guards will check it at the door. Thank you."]', '["Main Idea","Factual"]', -1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-A-018', 'L', 'lan', 'A', '{"kind":"ANN","audio":"audio/L/ANN-018.mp3","test":null,"qs":[{"stem":"What is being announced?","opts":["Free flu shots for students","A new health center building","A coffee shop opening","A change in the clinic''s hours"]},{"stem":"What do students need to bring?","opts":["An appointment letter","Their student ID","A coupon","A doctor''s note"]}]}', '[0,1]', '["*will offer free flu shots*. B — здание то же; C — кофе — бонус; D — часы не меняются","*please bring your student ID*. A — запись не нужна; C — купон дают; D — не упоминается","Good morning, everyone. The student health center will offer free flu shots next week. The clinic will be open in the student union on Tuesday and Wednesday from nine to four. No appointment is needed, but please bring your student ID. The shot takes only a few minutes. Students who get a flu shot will receive a coupon for a free coffee at the union café."]', '["Main Idea","Factual"]', -1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-A-023', 'L', 'lan', 'A', '{"kind":"ANN","audio":"audio/L/ANN-023.mp3","test":null,"qs":[{"stem":"What is being announced?","opts":["A new dining hall building","A cooking class","A price increase","Changes to the dining hall menu"]},{"stem":"Which meal''s hours will not change?","opts":["Breakfast","Dinner","Snacks","Lunch"]}]}', '[3,3]', '["*The dining hall is changing its menu*. A — здание то же; B — не упоминается; C — цены не упоминаются","*Lunch hours will stay the same*. A — завтрак меняется; B — ужин меняется; C — не упоминается","Hello, students. The dining hall is changing its menu this week. There will be a new salad bar and more vegetarian meals. Breakfast will now be served from seven to ten, and dinner from five to eight. Lunch hours will stay the same. Please tell the manager what you think of the new menu."]', '["Main Idea","Factual"]', -1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-A-024', 'L', 'lan', 'A', '{"kind":"ANN","audio":"audio/L/ANN-024.mp3","test":null,"qs":[{"stem":"What is the announcement mainly about?","opts":["A new bus route","A holiday bus schedule","A bus driver job","Higher bus prices"]},{"stem":"When will the regular schedule start again?","opts":["On December twenty-fifth","On January first","On January fifth","On the first of December"]}]}', '[1,2]', '["*During the winter holiday… different schedule*. A — маршрут тот же; C — не упоминается; D — цены не упоминаются","*start again on January fifth*. A — в этот день автобусов нет; B — в этот день нет; D — не упоминается","Attention, students. During the winter holiday, the campus bus will run on a different schedule. Buses will leave every hour instead of every twenty minutes. The last bus will leave at six in the evening. There will be no service on December twenty-fifth or January first. The regular schedule will start again on January fifth."]', '["Main Idea","Factual"]', -1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-A-025', 'L', 'lan', 'A', '{"kind":"ANN","audio":"audio/L/ANN-025.mp3","test":null,"qs":[{"stem":"What is the purpose of the announcement?","opts":["To ask students to give things to charity","To announce a new university website","To tell students where to look for lost items","To report a robbery"]},{"stem":"What happens to items after thirty days?","opts":["They are returned to the owners","They are given to charity","They are sold on the website","They are thrown away"]}]}', '[2,1]', '["*If you have lost something … visit the lost and found*. A — благотворительность — конец срока; B — сайт — доп. способ; D — не упоминается","*After that, they are given to charity*. A — не упоминается; C — не упоминается; D — не выбрасывают","Good afternoon. If you have lost something on campus, please visit the lost and found office in the student union. It''s open from nine to five, Monday through Friday. Items are kept for thirty days. After that, they are given to charity. You can also check photos of found items on the university website."]', '["Purpose","Factual"]', -1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-001', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-001.mp3","test":"T1","qs":[{"stem":"What is the main purpose of the announcement?","opts":["To inform students about changes to an upcoming lab session","To explain how students should write a lab report","To remind students to bring safety equipment","To announce that repairs to the science building are finished"]},{"stem":"What will students do during the session on Tuesday?","opts":["Carry out a new experiment","Hand in their second lab report","Review results from earlier labs","Practice using equipment in the library"]}]}', '[0,2]', '["B — о том, как писать отчёт, не говорится; C — наоборот, очки брать не нужно; D — ремонт ещё идёт","*go over your data from the last three labs* = review results. A — экспериментов не будет; B — дедлайн в пятницу, не во вторник; D — оборудования нет","Before you go, a quick change for next week. Our lab session on Tuesday won''t be in the usual room. The heating in the science building is being repaired, so we''ll meet in the library, room two-fourteen, on the second floor. Please bring your lab notebooks, but leave your goggles at home. We won''t be doing any experiments that day. Instead, we''ll go over your data from the last three labs. And if you haven''t handed in report two yet, Friday is the final deadline."]', '["Main Idea","Factual"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-002', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-002.mp3","test":"T1","qs":[{"stem":"What is the main purpose of the announcement?","opts":["To announce new exam dates","To inform students about longer library hours","To explain how to reserve books online","To remind students to return library books"]},{"stem":"What must students do to enter the library after nine o''clock?","opts":["Make a reservation online","Study on the third floor","Show their student ID","Join a group"]}]}', '[1,2]', '["A — даты экзаменов не названы; C — онлайн-бронь комнат, а не книг, и это деталь; D — возврат книг не упоминается","Прямо: *you''ll need your student ID to enter the building after nine*. A — бронь только для групповых комнат; B — комнаты закрываются в 11; D — не требуется","Attention, students. Starting Monday, the main library will stay open until midnight on weekdays to help with exam preparation. Previously, it closed at ten. Please note that the quiet study rooms on the third floor will still close at eleven, and you''ll need your student ID to enter the building after nine. If you''d like to reserve a group study room, you can do that on the library website, but reservations are limited to two hours."]', '["Main Idea","Factual"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-004', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-004.mp3","test":"T1","qs":[{"stem":"Why is the speaker making the announcement?","opts":["To invite students to a guest lecture","To introduce a new professor","To explain a change in a course schedule","To ask students to volunteer for a project"]},{"stem":"What should students do to reserve a seat?","opts":["Pay a small fee online","Sign up at the department office","Arrive at Hall B before four o''clock","Email Dr. Lopez directly"]}]}', '[0,1]', '["B — Dr. Lopez приглашённая гостья; C, D — не упоминаются","*please sign up at the department office by Wednesday*. A — вход бесплатный; C, D — не сказано","Attention, everyone. The Department of Environmental Studies is proud to welcome Dr. Maria Lopez on Thursday at four p.m. in Hall B. Dr. Lopez has spent twenty years studying how cities can reduce waste, and she''ll discuss projects in three countries. Admission is free, but seating is limited, so please sign up at the department office by Wednesday. Students who attend will receive extra credit in any environmental studies course."]', '["Purpose","Factual"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-007', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-007.mp3","test":"T2","qs":[{"stem":"What is the announcement mainly about?","opts":["A change to the shuttle route","Cancellation of weekend service","Longer waits between buses","The opening of a new sports center"]},{"stem":"Where can students get maps of the new route?","opts":["At the information desk","At the north gate","At the engineering building","At the sports center"]}]}', '[0,0]', '["*the campus shuttle will use a new route*. B — не упоминается; C — расписание не меняется; D — центр уже существует","*Maps … are available at the information desk*. B — остановку убирают; C — корпус упомянут как ближайший; D — новая остановка, но не карты","Attention, commuters. Beginning next Monday, the campus shuttle will use a new route. Instead of stopping at the north gate, buses will stop at the sports center, which is closer to the engineering building. The schedule stays the same, with buses leaving every twenty minutes between seven a.m. and nine p.m. Maps of the new route are available at the information desk and on the university app."]', '["Main Idea","Factual"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-008', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-008.mp3","test":"T2","qs":[{"stem":"Why is the speaker making the announcement?","opts":["To announce a change in citation rules","To ask students to register for a class","To introduce a new tutor","To tell students about a free workshop"]},{"stem":"What does the speaker imply about students who cannot attend?","opts":["They must register for another date","They will lose access to the tutor","They can still watch the workshop later","They need to email the Writing Center"]}]}', '[3,2]', '["*is offering a free workshop*. A — правила цитирования не меняются; B — регистрация не нужна; C — новый тьютор не представляется","*a recording will be posted … by Friday*. A — регистрация не нужна; B — не сказано; D — не сказано","Good afternoon. The Writing Center is offering a free workshop on research papers this Wednesday at three p.m. in room 210. A tutor will explain how to organize sources and avoid common citation mistakes. You don''t need to register, but bring a laptop or a notebook. If you can''t attend, a recording will be posted on the Writing Center website by Friday."]', '["Purpose","Inference"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-012', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-012.mp3","test":"T3","qs":[{"stem":"What is the announcement mainly about?","opts":["A new rule for showers","The cost of building repairs","A problem with the front desk","A temporary water shutoff"]},{"stem":"What does the speaker recommend residents do?","opts":["Store some water beforehand","Move to another building","Take showers before nine","Call the repair crew"]}]}', '[3,0]', '["*The water … will be turned off*. A — правила для душа не вводятся; B — стоимость не упоминается; C — стойка — для вопросов","*Please fill a few bottles in advance*. B — переезд не предлагается; C — душ нельзя, но это не рекомендация; D — звонить нужно на стойку","Attention, residents of Baker Hall. The water in the building will be turned off this Thursday from nine a.m. until two p.m. for repairs to the main pipe. Please fill a few bottles in advance for drinking, and avoid using the showers and sinks during that time. Water will return gradually after two, so it may look cloudy for a few minutes. If you have any questions, please contact the front desk."]', '["Main Idea","Method"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-013', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-013.mp3","test":"T3","qs":[{"stem":"What is the purpose of the announcement?","opts":["To announce the results of a recent game","To tell students how to join intramural soccer","To ask for volunteers to coach teams","To explain a change in the game schedule"]},{"stem":"What can students without a team do?","opts":["Sign up on the department website only","Wait for the next season","Play on Wednesday evenings","Attend a meeting at the recreation center"]}]}', '[1,3]', '["*Registration … is now open*. A — результатов нет; C — тренеры не нужны; D — расписание не меняется","*Come to the recreation center on Wednesday at six*. A — сайт — для команд; B — не упоминается; C — игры по воскресеньям","Good afternoon, students. Registration for intramural soccer is now open. Teams of seven to ten players can sign up at the recreation center or on the department website. The deadline is Friday, September twentieth. Games will be played on Sunday afternoons, starting in early October. If you don''t have a team, don''t worry. Come to the recreation center on Wednesday at six, and we''ll help you join one."]', '["Purpose","Factual"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-019', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-019.mp3","test":null,"qs":[{"stem":"What is the purpose of the announcement?","opts":["To recruit students for a company","To announce new career center staff","To explain how to write a résumé","To inform students about a career fair"]},{"stem":"What can students do this week if they want help with their résumés?","opts":["Attend a workshop in the gymnasium","Email the companies directly","Make an appointment at the career center","Order copies at the bookstore"]}]}', '[3,2]', '["*The annual career fair will take place*. A — компании сами будут; B — сотрудники не упоминаются; C — объявление не учит писать","*the career center offers free appointments this week*. A — ярмарка — на следующей неделе; B — не упоминается; D — не упоминается","Good afternoon, seniors. The annual career fair will take place next Wednesday in the gymnasium from ten to three. More than sixty companies will be there, including several from the technology and health sectors. Bring several copies of your résumé, and dress professionally. If you''d like feedback on your résumé first, the career center offers free appointments this week."]', '["Purpose","Method"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-020', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-020.mp3","test":null,"qs":[{"stem":"What should drivers do while Lot C is closed?","opts":["Use the shuttle from home","Pay for parking downtown","Park behind the library","Park in Lot F"]},{"stem":"What can be inferred about Lot F?","opts":["It is farther from the main campus than Lot C","It is closed for repairs","It costs extra to use","It is only for faculty"]}]}', '[3,0]', '["*may park in Lot F*. A — шаттл идёт от Lot F; B — не упоминается; C — не упоминается","Нужен шаттл от Lot F до кампуса. B — закрыт Lot C; C — бесплатно; D — не упоминается","Attention, drivers. Parking Lot C will be closed for repaving from Monday through Thursday of next week. During that time, commuters may park in Lot F, behind the science building, at no extra cost. A free shuttle will run from Lot F to the main campus every ten minutes. We apologize for the inconvenience and thank you for your patience."]', '["Method","Inference"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-026', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-026.mp3","test":null,"qs":[{"stem":"What is the main purpose of the announcement?","opts":["To announce a new history course","To promote a series of lectures","To introduce a new professor","To explain a change in the schedule"]},{"stem":"How can students earn extra credit?","opts":["By arriving early","By attending the first lecture","By writing a response to a lecture","By volunteering at the department"]}]}', '[1,2]', '["*pleased to announce its spring lecture series*. A — курс не упоминается; C — докладчик — гость; D — расписание не меняется","*writing a short response to any lecture*. A — место ограничено, но кредит не даёт; B — не упоминается; D — не упоминается","The Department of History is pleased to announce its spring lecture series, Voices of the Past. Each Thursday at six, a different scholar will speak about life in a different historical period. The first lecture, on daily life in ancient Rome, will be given by Dr. Maria Lopez in Room two-ten. All lectures are free, but seating is limited, so please arrive early. Students may earn extra credit by writing a short response to any lecture."]', '["Purpose","Method"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-027', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-027.mp3","test":null,"qs":[{"stem":"Why will the computer lab be closed?","opts":["It will receive updates and new computers","The software is broken","The room will be painted","The library needs the equipment"]},{"stem":"What can students do if they need to print over the weekend?","opts":["Go to the library lab","Wait until Monday","Visit Hartley Hall","Ask the maintenance team"]}]}', '[0,0]', '["*software will be updated, and new computers will be installed*. B — не сломан; C — не упоминается; D — не упоминается","*go to the lab in the library*. B — можно сразу в библиотеку; C — Hartley закрыт; D — не упоминается","Attention, students. The computer lab in Hartley Hall will be closed for maintenance from Friday at five p.m. until Monday morning. During this time, all software will be updated, and new computers will be installed. Students who need to print or use special software may go to the lab in the library, which is open all weekend. We apologize for any inconvenience."]', '["Factual","Method"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-B-028', 'L', 'lan', 'B', '{"kind":"ANN","audio":"audio/L/ANN-028.mp3","test":null,"qs":[{"stem":"What does the speaker say students must do before they register?","opts":["Pay their tuition","Meet with their academic advisor","Wait until Wednesday","Choose a new major"]},{"stem":"What can be inferred about first-year students?","opts":["They cannot register for fall classes","They do not need an advisor","They register after the other groups","They register on Monday"]}]}', '[1,2]', '["*meet with your academic advisor to approve your plan*. A — не упоминается; C — только первокурсники; D — не упоминается","*First-year students will register on Wednesday*. A — регистрируются в среду; B — нужен всем; D — понедельник — старшие","Good morning. Registration for fall classes opens next Monday at eight a.m. Students will register in groups, based on how many credits they have earned. Seniors go first, then juniors, then sophomores. First-year students will register on Wednesday. Before you register, please meet with your academic advisor to approve your plan. Without this approval, the system will not let you sign up."]', '["Method","Inference"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-C-003', 'L', 'lan', 'C', '{"kind":"ANN","audio":"audio/L/ANN-003.mp3","test":"T1","qs":[{"stem":"Why will the university run a free shuttle?","opts":["The north lot will be closed all year","The east lot is far from most classrooms","Bus passes are too expensive for students","Permits for the east lot have sold out"]},{"stem":"What can be inferred about students who already have a north-lot permit?","opts":["They must pay for a new permit","They can park in the east lot without new paperwork","They will receive a free bus pass","They must use the shuttle every day"]}]}', '[1,1]', '["Прямо: *The east lot is a ten-minute walk… so… shuttle*. A — стройка идёт, срок не назван; C, D — не сказано","*permits… honored in the east lot* + *you don''t need to do anything*. A — противоположно; C — скидка, не бесплатно; D — ездить на шаттле не обязательно","Good afternoon, everyone. Construction on the north parking lot begins next week, so permits for that lot will be honored in the east lot instead. The east lot is a ten-minute walk from most classrooms, so the university will run a free shuttle every fifteen minutes. If you''d rather not drive, student services is offering a discount on monthly bus passes. If you''ve already paid for a north-lot permit, you don''t need to do anything."]', '["Purpose","Inference"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-C-005', 'L', 'lan', 'C', '{"kind":"ANN","audio":"audio/L/ANN-005.mp3","test":null,"qs":[{"stem":"What is the announcement mainly about?","opts":["A change in the registration deadline","The role of academic advisors","New classes available next semester","A temporary shutdown of the online registration system"]},{"stem":"What does the speaker suggest students should do?","opts":["Choose their classes before the portal closes","Visit the advisors on Sunday","Wait until the upgrade is finished","Change their schedules after the upgrade"]}]}', '[3,0]', '["A — срок не меняется; B, C — не главная тема","*you should do so before Friday at seven*. C — противоположно; B — советники только в пятницу; D — не сказано","Good morning. This is a reminder about spring registration. Because of a system upgrade, the online portal will be unavailable from Friday evening until Sunday morning. If you haven''t chosen your classes yet, you should do so before Friday at seven. After the upgrade, you''ll be able to see open spots in real time, which hasn''t been possible before. Advisors will also stay in their offices until six on Friday to answer questions."]', '["Main Idea","Inference"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-C-009', 'L', 'lan', 'C', '{"kind":"ANN","audio":"audio/L/ANN-009.mp3","test":"T2","qs":[{"stem":"What is the announcement mainly about?","opts":["The cancellation of a scholarship","The names of this year''s winners","New majors eligible for funding","Changes to a scholarship application"]},{"stem":"What does the speaker suggest students should do?","opts":["Wait for another announcement","Apply for a different scholarship","Ask their professors to apply","Prepare their materials earlier than before"]}]}', '[3,3]', '["*an important change*: срок и письма. A — стипендия остаётся; B — победители не названы; C — не упоминается","*moved … to March first … please plan ahead*. A — срок уже объявлен; B — не сказано; C — профессора не подают заявку","Students applying for the Hartwell Scholarship, please note an important change. This year, the application deadline has moved from March fifteenth to March first. In addition, applicants must now submit two letters of recommendation instead of one, and at least one letter must come from a professor in the applicant''s major. Applications that arrive late will not be considered, so please plan ahead."]', '["Main Idea","Inference"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-C-011', 'L', 'lan', 'C', '{"kind":"ANN","audio":"audio/L/ANN-011.mp3","test":"T2","qs":[{"stem":"According to the speaker, what is the benefit of showing videos?","opts":["Winners can speak longer","The ceremony can end before nine","Each department gets more awards","Refreshments can be served earlier"]},{"stem":"What does the speaker imply about the video format?","opts":["It was requested by the winners","It is different from the usual way of announcing winners","It will cost more than a live ceremony","It will be used every year"]}]}', '[1,1]', '["*which lets us finish before nine*. A — не упоминается; C — не упоминается; D — угощение после церемонии","*Instead of announcing winners one by one*. A — не сказано; C — не сказано; D — не сказано","Good evening, and welcome to the Student Achievement Awards. A quick note about tonight''s schedule. Instead of announcing winners one by one, we''ll show a short video about each department''s winners, which lets us finish before nine. Please hold your applause until the end of each video. Refreshments will be served in the lobby afterward."]', '["Factual","Inference"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-C-014', 'L', 'lan', 'C', '{"kind":"ANN","audio":"audio/L/ANN-014.mp3","test":"T3","qs":[{"stem":"Why is the lecture being rescheduled?","opts":["The speaker''s flight was canceled","The auditorium is unavailable","Too few tickets were sold","Dr. Hayes became ill"]},{"stem":"What does the speaker imply about ticket holders?","opts":["They will not need new tickets","They must pick up new tickets","They can only attend if they request a refund","They should arrive after nine"]}]}', '[0,0]', '["*delayed because of a canceled flight*. B — место остаётся прежним; C — не упоминается; D — болезнь не упоминается","*Tickets will remain valid*. B — действуют прежние; C — возврат — выбор; D — после девяти приезжает докладчик","Good evening, everyone. Unfortunately, tonight''s guest speaker, Dr. Hayes, has been delayed because of a canceled flight. She''s now expected to arrive after nine, which is too late for the lecture. Instead, the organizers have rescheduled the talk for next Tuesday at the same time and place. Tickets will remain valid, and anyone who can''t attend may request a refund at the box office. We apologize for the inconvenience."]', '["Factual","Inference"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-C-016', 'L', 'lan', 'C', '{"kind":"ANN","audio":"audio/L/ANN-016.mp3","test":"T3","qs":[{"stem":"What is new about the gallery?","opts":["It offers lessons to students","It is open on weekends only","It charges visitors a fee","It includes a studio where artists work"]},{"stem":"What is the speaker''s attitude toward the reopening?","opts":["Concerned","Neutral","Disappointed","Enthusiastic"]}]}', '[3,3]', '["*a studio where visitors can watch artists at work*. A — уроки не упоминаются; B — дни не ограничены; C — студентам бесплатно","*exciting news*; восторженный тон. A — тревоги нет; B — тон оживлённый; C — нет разочарования","Art lovers, we have exciting news. After two years of renovations, the university art gallery will reopen next Monday. The new space doubles the exhibition area and includes a studio where visitors can watch artists at work. Admission is free for students, and a special opening exhibit will feature works by alumni from the past decade. Guided tours are offered at noon each day, but reservations are required for groups larger than five."]', '["Factual","Attitude"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-C-021', 'L', 'lan', 'C', '{"kind":"ANN","audio":"audio/L/ANN-021.mp3","test":null,"qs":[{"stem":"Why has the deadline been changed?","opts":["To reduce the late fee","To increase the number of graduates","To match the graduate schools'' deadlines","To give the registrar more time to check requirements"]},{"stem":"What does the speaker imply about students who applied before the announcement?","opts":["They must pay a late fee","They must reapply","Their applications are still valid","They will graduate early"]}]}', '[3,2]', '["*so that the registrar has enough time*. A — штраф остаётся; B — не упоминается; C — не упоминается","*do not need to take any action*. A — штраф для опоздавших; B — переподавать не надо; D — не упоминается","Students applying to graduate this spring should note an important change. The deadline for submitting graduation applications has been moved from March first to February fifteenth, so that the registrar has enough time to verify requirements. Applications submitted after the new deadline will incur a late fee of fifty dollars. Students who have already applied do not need to take any action."]', '["Factual","Inference"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-C-022', 'L', 'lan', 'C', '{"kind":"ANN","audio":"audio/L/ANN-022.mp3","test":null,"qs":[{"stem":"What is the main purpose of the announcement?","opts":["To announce a new computer lab","To warn students about a temporary network disruption","To ask students to test the network","To explain how to use the library catalog"]},{"stem":"What does the speaker suggest students do if they need the internet urgently?","opts":["Wait until Sunday","Use wired connections in the computer labs","Visit the library","Use their phones"]}]}', '[1,1]', '["*Wi-Fi network will be upgraded… connection will be intermittent*. A — лаборатории уже есть; C — тест не просят; D — каталог лишь пример","*use the wired connections in the computer labs*. A — не предлагается; C — каталог недоступен; D — не упоминается","Please be advised that the campus Wi-Fi network will be upgraded this Saturday between two and eight a.m. During this period, the connection will be intermittent, and some services, including the online library catalog, may be unavailable. Students who need access for urgent work are encouraged to use the wired connections in the computer labs. The upgrade is expected to double network speeds across all residence halls."]', '["Purpose","Method"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-C-029', 'L', 'lan', 'C', '{"kind":"ANN","audio":"audio/L/ANN-029.mp3","test":null,"qs":[{"stem":"What was different about the previous policy?","opts":["Copying was allowed","All offenses led to a committee review","Students were not required to cite sources","Penalties depended on the instructor"]},{"stem":"Why does the speaker mention the workshops?","opts":["To explain how violations are punished","To offer students help avoiding violations","To announce a new course","To ask instructors to attend"]}]}', '[3,1]', '["*Previously, penalties varied by instructor*. A — не утверждается; B — только повторное нарушение; C — не утверждается","*Workshops on proper citation*. A — наказания описаны раньше; C — курса нет; D — не упоминается","Attention, students. The university has updated its policy on academic integrity. Beginning this semester, any student found to have copied material without citing it will receive a zero on the assignment, and a second offense will lead to review by a committee. Previously, penalties varied by instructor. The change is intended to make expectations consistent across all courses. Workshops on proper citation will be offered every Tuesday at noon in the library."]', '["Factual","Purpose"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-C-030', 'L', 'lan', 'C', '{"kind":"ANN","audio":"audio/L/ANN-030.mp3","test":null,"qs":[{"stem":"What will the university do for inconvenienced members?","opts":["Reduce this semester''s fees","Provide temporary classes","Close the center for a month","Give them a free month of membership"]},{"stem":"What can be inferred about the renovations?","opts":["The whole center will close","Only the pool will be available","Some facilities will remain available during construction","The project will finish in January"]}]}', '[3,2]', '["*receive a free month of membership*. A — не упоминается; B — не упоминается; C — не закрывается","*the main pool and basketball courts will remain open*. A — не закрыт целиком; B — и корты тоже; D — начало — январь, срок 5 месяцев","Students and staff, the Wellness Center will undergo renovations starting in January. The project, which is expected to take five months, will add a new climbing wall, a larger weight room, and an indoor track. While construction is underway, the main pool and basketball courts will remain open, but the locker rooms will be limited. Temporary lockers will be set up next to the pool. Members who are inconvenienced will receive a free month of membership once the work is finished."]', '["Factual","Inference"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-ANN-C-031', 'L', 'lan', 'C', '{"kind":"ANN","audio":"audio/L/ANN-031.mp3","test":null,"qs":[{"stem":"What is the main purpose of the announcement?","opts":["To inform students about changes to the scholarship application","To announce a new scholarship","To extend the scholarship deadline","To explain how to write a letter"]},{"stem":"What does the speaker imply about students who have already started their applications?","opts":["They must start over","They will receive extra time","They no longer need an essay","They may use their earlier materials"]}]}', '[0,3]', '["*made two changes to this year''s application*. B — новой стипендии нет; C — срок не меняется; D — письмо — лишь деталь","*will be allowed to submit their previous materials*. A — не обязаны; B — срок прежний; C — эссе всё равно нужно","Good afternoon. The scholarship office has made two changes to this year''s application. First, applicants must now submit a two-page personal essay, instead of a single paragraph. Second, letters of recommendation must come directly from the writers, not from the students. The deadline remains March first. Students who have already begun applications will be allowed to submit their previous materials, but they are encouraged to follow the new guidelines."]', '["Purpose","Inference"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-A-012', 'L', 'lco', 'A', '{"kind":"CONV","audio":"audio/L/CONV-012.mp3","test":"T2","qs":[{"stem":"What is the man''s problem?","opts":["His drink is too small","He received the wrong sandwich","He is late for the cafeteria","He cannot find the cashier"]},{"stem":"What will the woman give the man for free?","opts":["A sandwich","A drink","A dessert","A coupon"]}]}', '[1,1]', '["*I ordered a chicken sandwich, but this one has fish*. A — сок он просит сам; C — он торопится на урок, не в кафетерий; D — не упоминается","*I''ll add a free drink*. A — сэндвич просто заменят; C — не упоминается; D — не упоминается","Man: Excuse me, I ordered a chicken sandwich, but this one has fish.\nWoman: Oh, I''m so sorry. That''s my mistake. Let me fix it right away.\nMan: Thanks. I''m in a hurry. My class starts in ten minutes.\nWoman: It''ll take two minutes. And I''ll add a free drink for the trouble.\nMan: That''s very kind. A small orange juice, please."]', '["Main Idea","Factual"]', -1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-A-019', 'L', 'lco', 'A', '{"kind":"CONV","audio":"audio/L/CONV-019.mp3","test":"T3","qs":[{"stem":"What does the man order?","opts":["A tea and a chocolate muffin","A coffee and a blueberry muffin","A coffee and a banana muffin","A banana muffin only"]},{"stem":"Why can''t the man get a blueberry muffin?","opts":["They are sold out","They cost too much","The shop is closing","They are not made on Mondays"]}]}', '[2,0]', '["Сначала черничный, потом *Banana, please*. A — чай не заказывает; B — черничные закончились; D — кофе он тоже заказывает","*the blueberry muffins are sold out*. B — цена не причина; C — закрытие не упоминается; D — понедельник не упоминается","Woman: Hi. What can I get for you?\nMan: A large coffee, please. And a blueberry muffin.\nWoman: I''m sorry, the blueberry muffins are sold out. We have banana or chocolate.\nMan: Banana, please. How much is it?\nWoman: That''s six dollars and fifty cents.\nMan: Okay. Here you are."]', '["Factual","Factual"]', -1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-A-022', 'L', 'lco', 'A', '{"kind":"CONV","audio":"audio/L/CONV-022.mp3","test":null,"qs":[{"stem":"Why does the man come to the bookstore?","opts":["To return a textbook","To buy a new textbook","To sell his old books","To ask about a job"]},{"stem":"What will the man do before buying another book?","opts":["Check the edition number online","Ask his professor","Write his name in the book","Find the receipt"]}]}', '[0,0]', '["*it''s the wrong edition. Can I return it?* B — не покупает новую; C — не продаёт; D — работа не упоминается","*I''ll check the edition number online first*. B — профессор не упоминается; C — в книге писать нельзя; D — чек у него уже есть","Man: Hi, I bought this textbook yesterday, but it''s the wrong edition. Can I return it?\nWoman: Yes, if you have the receipt and the book is not marked.\nMan: Here''s the receipt. I haven''t written in it.\nWoman: Great. Do you want a refund or a different book?\nMan: A refund, please. I''ll check the edition number online first."]', '["Main Idea","Factual"]', -1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-A-023', 'L', 'lco', 'A', '{"kind":"CONV","audio":"audio/L/CONV-023.mp3","test":null,"qs":[{"stem":"What does the woman want to find?","opts":["The fountain","The student center","The registrar''s office","A classroom"]},{"stem":"Why does the man say the woman should hurry?","opts":["The office closes soon","The building is far away","It is raining outside","The fountain is closed"]}]}', '[2,0]', '["*where the registrar''s office is*. A — фонтан — ориентир; B — не упоминается; D — не упоминается","*The office closes at four*. B — здание рядом; C — не упоминается; D — не упоминается","Woman: Excuse me, do you know where the registrar''s office is?\nMan: Sure. It''s in the Admin Building, on the first floor.\nWoman: Is that the tall brick building by the fountain?\nMan: Yes, that''s the one. The office closes at four, so you should hurry.\nWoman: Thanks! It''s already three thirty."]', '["Main Idea","Factual"]', -1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-A-028', 'L', 'lco', 'A', '{"kind":"CONV","audio":"audio/L/CONV-028.mp3","test":null,"qs":[{"stem":"Why does the man talk to the woman?","opts":["To return some books","To ask about his student ID","To get a library card","To find a quiet room"]},{"stem":"How long can the man keep the books?","opts":["Three weeks","Five minutes","Ten days","One month"]}]}', '[2,0]', '["*I''d like to get a library card*. A — возврат не упоминается; B — ID — лишь документ; D — комнаты не упоминаются","*Three weeks*. B — 5 минут — выдача карты; C — 10 — число книг; D — не упоминается","Man: Hi, I''d like to get a library card.\nWoman: Sure. Do you have your student ID with you?\nMan: Yes, here it is.\nWoman: Thanks. Your card will be ready in five minutes. You can borrow up to ten books at a time.\nMan: Great. How long can I keep them?\nWoman: Three weeks. You can renew them online."]', '["Main Idea","Factual"]', -1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-A-029', 'L', 'lco', 'A', '{"kind":"CONV","audio":"audio/L/CONV-029.mp3","test":null,"qs":[{"stem":"What does the woman want to get?","opts":["A gym membership","A student ID","A parking permit","A bus pass"]},{"stem":"How much does the pass cost for students?","opts":["Forty dollars a month","Twenty dollars a month","Twenty-five dollars a month","Fifty dollars a month"]}]}', '[3,2]', '["*how I can get a bus pass*. A — спортзал — ориентир; B — ID уже есть; C — не упоминается","*students get a discount. It''s only twenty-five*. A — цена без скидки; B — не упоминается; D — не упоминается","Woman: Do you know how I can get a bus pass?\nMan: You can get one at the transportation office. It''s next to the gym.\nWoman: How much is it?\nMan: Forty dollars a month, but students get a discount. It''s only twenty-five.\nWoman: That''s great. Do I need a photo?\nMan: No, just your student ID."]', '["Main Idea","Factual"]', -1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-A-030', 'L', 'lco', 'A', '{"kind":"CONV","audio":"audio/L/CONV-030.mp3","test":null,"qs":[{"stem":"What is the man worried about?","opts":["Homework due tomorrow","Missing lunch","Losing his notes","A quiz tomorrow"]},{"stem":"What will the speakers probably do after lunch?","opts":["Study together","Take the quiz","Visit the professor","Go to the library alone"]}]}', '[3,0]', '["*I forgot about the quiz*. A — домашка — в четверг; B — обед — время занятия; C — он просит чужие конспекты","*Let''s study together after lunch*. B — квиз завтра; C — не упоминается; D — они будут вместе","Man: Did you write down the homework for biology?\nWoman: Yes. We need to read chapter six and answer the questions at the end.\nMan: Is it due tomorrow?\nWoman: No, it''s due on Thursday. But the quiz is tomorrow.\nMan: Oh no, I forgot about the quiz. Can I look at your notes?\nWoman: Sure. Let''s study together after lunch."]', '["Main Idea","Inference"]', -1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-001', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-001.mp3","test":"T1","qs":[{"stem":"What are the speakers mainly discussing?","opts":["Why the man stopped going to the gym","The schedule of services at the student center","Whether the man should buy a new bike","How the man can deal with a problem with his bike"]},{"stem":"What will the man most likely do next?","opts":["Wait until Thursday to have his bike repaired","Try to repair the tire himself","Walk to the gym in the rain","Ask the woman to fix the tire for him"]}]}', '[3,1]', '["A — он не бросал зал, пропустил один раз; B — расписание упомянуто как деталь; C — покупку не обсуждают","A — его не устраивает ждать (*Ugh, two days away*); C — прямо отказывается; D — такого не просит. Подсказка: *video online* + *I''ll give it a shot*","Woman: Hey, Liam, weren''t you supposed to be at the gym this morning?\nMan: Yeah, I was gonna go, but my bike''s got a flat tire. And I''m not walking all the way across campus in this rain.\nWoman: You know the student center does free bike repairs, right? Only on Thursdays, though.\nMan: Thursdays? Ugh, that''s two days away.\nWoman: Well, they also lend out tools at the front desk. You could just fix it yourself.\nMan: Me? Fix a tire? I''d probably make it worse... Actually, um, there''s gotta be a video online. Okay, I''ll give it a shot."]', '["Main Idea","Inference"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-002', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-002.mp3","test":"T1","qs":[{"stem":"Why does the man go to the office?","opts":["To report a lost wallet","To pick up a replacement student ID","To ask about dining hall prices","To apply for a digital license"]},{"stem":"According to the woman, what will happen tomorrow?","opts":["The office will close early","The man''s phone will stop working","The old ID will no longer work at the dining hall","A new photo will be required"]}]}', '[1,2]', '["A — кошелёк оставил в общежитии, не потерял; C — столовая упомянута только в предупреждении; D — цифровые права уже есть","A, B, D — не упоминаются; прямая фраза: *your old ID stops working at the dining hall tomorrow*","Man: Hi, I''m here to pick up my student ID. I ordered a replacement last week.\nWoman: Let me check... Okay, it''s ready, but I''ll need to see another photo ID first.\nMan: Oh. I left my wallet in my dorm room. I only have my phone.\nWoman: Well, a digital license on your phone works, actually. Do you have that?\nMan: Yes, I do. Here you go.\nWoman: Perfect. And a heads-up: your old ID stops working at the dining hall tomorrow, so be sure to switch over."]', '["Main Idea","Factual"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-004', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-004.mp3","test":"T1","qs":[{"stem":"Why does the man go to the bookstore?","opts":["To buy a book for another class","To return a textbook he no longer needs","To ask about a missing receipt","To find out when a new edition will arrive"]},{"stem":"What does the employee imply when she says the man is \"just in time\"?","opts":["The new edition is almost sold out","The return period is almost over","The store is about to close","The refund is available only today"]}]}', '[1,1]', '["A — другой курс не упоминается; C — чек у него есть; D — новое издание уже есть в магазине","*Normally you have seven days* и покупка была неделю назад — срок почти истёк. A, C, D — не сказано","Man: Hi, I''d like to return this textbook. I bought it last week, but my professor just switched to a different edition.\nWoman: Do you have your receipt? I also have to check that the book hasn''t been written in.\nMan: I have the receipt, and I haven''t opened it. It''s still in the plastic wrap.\nWoman: Great. Then I can give you a full refund. Normally you have seven days, so you''re just in time. Will you need the new edition?\nMan: Yes, please. Where would I find it?\nWoman: Aisle four, on the left."]', '["Main Idea","Inference"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-005', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-005.mp3","test":"T1","qs":[{"stem":"What will the man probably do before the film?","opts":["Call the other club members","Review for his chemistry quiz","Help set up the equipment","Write a review of the documentary"]},{"stem":"Why does the woman mention that the film is only ninety minutes?","opts":["To explain why the club chose it","To suggest that the man has enough time","To warn him that it will end late","To compare it with a longer film"]}]}', '[1,1]', '["*If I study until five-thirty…* — он будет готовиться к тесту. A, C, D — не упоминаются","Она убеждает его, что фильм короткий. A, C, D — не сказано","Woman: Hey, are you coming to the film club tonight? We''re showing a documentary about deep-sea animals.\nMan: I''d like to, but I have a chemistry quiz tomorrow, and I haven''t even started studying.\nWoman: Oh, right. Well, it''s only ninety minutes, and it starts at six.\nMan: Hmm. If I study until five-thirty, I could stay for the first half and leave early.\nWoman: Or you could skip the studying and just come.\nMan: Very funny. I''ll see how much I get done."]', '["Inference","Purpose"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-007', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-007.mp3","test":"T1","qs":[{"stem":"What problem does the man have?","opts":["He is finding only very old articles","He cannot open the library website","He does not know how to cite sources","He cannot decide on a topic"]},{"stem":"According to the librarian, how can the man get more specific results?","opts":["By asking another library","By searching in a different database","By adding key words to his search","By choosing a longer article"]}]}', '[0,2]', '["*everything I find is from the nineties*. B, C, D — не упоминаются","*if you add the word ''wind'' or ''solar''*. A — только если нет доступа к полному тексту; B, D — не сказано","Man: Excuse me, I''m looking for articles about renewable energy, but everything I find is from the nineties.\nWoman: Have you tried filtering by publication date? Most of our databases let you do that.\nMan: I didn''t know that. Where''s the filter?\nWoman: On the left side of the search page. And if you add the word \"wind\" or \"solar,\" you''ll get more specific results.\nMan: I''m supposed to write about wind power, so that helps a lot.\nWoman: Great. And if you can''t open a full article, come back, and I''ll request it from another library."]', '["Main Idea","Factual"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-008', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-008.mp3","test":"T2","qs":[{"stem":"Why does the man visit the health center?","opts":["To renew his student ID","To cancel an appointment","To find out how to get a flu shot","To ask for medicine for a cold"]},{"stem":"What does the woman tell the man to bring?","opts":["A note from a doctor","His student ID","A short-sleeved shirt","An insurance card"]}]}', '[2,1]', '["Первая реплика: *I''d like to get a flu shot*. A — ID нужно только принести; B — запись не отменяется; D — лекарства не упоминаются","*Just your student ID*. A — не упоминается; C — рубашку нужно надеть, а не принести; D — не упоминается","Man: Hi, I''d like to get a flu shot. Do I need an appointment?\nWoman: Not exactly. We have walk-in hours on Tuesdays and Thursdays, from ten to two.\nMan: Today''s Wednesday. Is there any other way?\nWoman: You can book a slot online, but the earliest one is tomorrow at eleven.\nMan: Tomorrow works. Do I have to bring anything?\nWoman: Just your student ID. And wear a short-sleeved shirt, if you can."]', '["Main Idea","Factual"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-009', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-009.mp3","test":"T2","qs":[{"stem":"What are the speakers mainly discussing?","opts":["Where to find a cheaper hotel at the lake","Whether to rent a car for the trip","How to travel to a lake for spring break","How to get up early"]},{"stem":"What will the woman probably do tonight?","opts":["Ask her cousin about a ride","Buy a bus ticket","Book a parking space","Call the lake resort"]}]}', '[2,0]', '["Обсуждают варианты поездки: автобус, своя машина, поездка с кузиной. A — отель не обсуждается; B — аренда не обсуждается; D — деталь, не тема","*Could you ask her tonight?* — просит спросить кузину. B — автобус дорогой и ранний; C — парковка нужна только при поездке на своей машине; D — не упоминается","Woman: Have you decided how you''re getting to the lake for spring break?\nMan: Still thinking. Driving takes six hours, but a bus ticket is only thirty dollars.\nWoman: Thirty each way? That adds up. And the bus leaves at five in the morning.\nMan: True, and I''m not a morning person. But I''d have to pay for gas and parking if I drive.\nWoman: My cousin has a car. She might give us a ride if we split the gas.\nMan: Now that''s an idea. Could you ask her tonight?"]', '["Main Idea","Inference"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-011', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-011.mp3","test":"T2","qs":[{"stem":"What problem does the woman describe?","opts":["Her laptop loses its Wi-Fi connection","Her laptop will not turn on","The library has no Wi-Fi","She forgot her password"]},{"stem":"According to the man, why might the library connection be unreliable?","opts":["The wireless driver is old","The building is too old","The dorm network interferes","Many people are using the network"]}]}', '[0,3]', '["*keeps disconnecting from the campus Wi-Fi*. B — не упоминается; C — в библиотеке сеть есть, но перегружена; D — не упоминается","*The library network is busy this time of year*. A — это его вопрос к ней, не причина; B — не упоминается; C — в общежитии всё в порядке","Woman: My laptop keeps disconnecting from the campus Wi-Fi. It happens every few minutes.\nMan: Does it happen everywhere on campus, or only in certain buildings?\nWoman: Mostly in the library. Actually, in the dorm, it''s fine.\nMan: That helps. The library network is busy this time of year. Have you updated your wireless driver recently?\nWoman: I don''t even know how to do that.\nMan: No problem. Leave it with us until tomorrow, and we''ll update it and test the connection."]', '["Main Idea","Factual"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-014', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-014.mp3","test":"T2","qs":[{"stem":"Why does the man talk to the advisor?","opts":["To ask for a different room","To report noise that bothers him","To change the quiet hours","To complain about an early lab"]},{"stem":"What does the advisor say she will do?","opts":["Move the man to another floor","Talk to the residents without naming the man","Change the rules about quiet hours","Call the man''s professor"]}]}', '[1,1]', '["Первая реплика: шум на этаже. A — переезд не просит; C — правила не меняет; D — лаб — причина недосыпа","*I''ll talk to the residents tomorrow without mentioning your name*. A — не предлагает; C — правила не меняет; D — не упоминается","Man: Hi, I wanted to talk about the noise on my floor. Someone plays music pretty late.\nWoman: Thanks for telling me. Quiet hours start at eleven on weeknights. Is the music after that?\nMan: Yes, usually around midnight. I have an early lab, so it''s hard to sleep.\nWoman: I understand. Do you know which room it is?\nMan: I think it''s 412, but I''m not sure.\nWoman: I''ll talk to the residents tomorrow without mentioning your name."]', '["Purpose","Factual"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-015', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-015.mp3","test":"T3","qs":[{"stem":"Why does the man talk to the woman?","opts":["To find out about joining the gym","To cancel his membership","To ask for a refund","To apply for a job at the gym"]},{"stem":"What does the woman say about canceling the membership?","opts":["It costs an extra fee","It can only be done in person","It is not possible in the first month","Members must give a week''s notice"]}]}', '[0,3]', '["*I''d like to ask about a membership*. B — он ещё не член; C — возврат не обсуждается; D — работа не упоминается","*you have to tell us a week before*. A — плата не упоминается; B — способ не упоминается; C — ограничение не упоминается","Man: Hi, I''d like to ask about a membership. Is there a student rate?\nWoman: Yes. It''s twenty dollars a month if you show your student ID.\nMan: That''s good. Is there a contract I have to sign?\nWoman: No contract. You can cancel any time, but you have to tell us a week before.\nMan: Great. Can I try the gym today before I sign up?\nWoman: Sure. We offer a free day pass for new members."]', '["Main Idea","Factual"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-016', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-016.mp3","test":"T3","qs":[{"stem":"Why might the man miss the meeting?","opts":["He is traveling to Spain","He has a lab at the same time","He has not received the email","He does not want to study abroad"]},{"stem":"What does the man imply about studying abroad?","opts":["He prefers to study in his own country","Cost is a concern for him","He already speaks Spanish well","He thinks the meeting is unnecessary"]}]}', '[1,1]', '["*I have a lab until five*. A — Испания — планы женщины; C — он получил письмо; D — интерес есть, но дорого","*it''s expensive. I''ll wait … scholarships*. A — такого нет; C — нужны языки у женщины; D — он хочет узнать о стипендиях","Woman: Did you get the email about the study abroad meeting?\nMan: I did, but I''m not sure I can go. It''s at four on Thursday, and I have a lab until five.\nWoman: That''s a problem. They said they''d record the session, though.\nMan: Good. Are you going to apply for the program?\nWoman: I''m thinking about Spain. My Spanish needs work, and living there would help.\nMan: I''d love that, but it''s expensive. I''ll wait and hear about scholarships first."]', '["Factual","Inference"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-018', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-018.mp3","test":"T3","qs":[{"stem":"Why did the man come to the post office?","opts":["To send a letter","To change his address","To get a package","To report a lost notice"]},{"stem":"What will the man probably do next?","opts":["Buy stamps at another window","Return to his hotel","Fill out a form","Wait for a letter"]}]}', '[2,0]', '["*I''m here to pick up a package*. A — отправка не упоминается; B — адрес не упоминается; D — уведомление у него есть","*The stamps are at the next window*. B — не упоминается; C — формы не упоминаются; D — не упоминается","Man: Hi, I''m here to pick up a package. The notice says it''s been here since Monday.\nWoman: I can help. May I see your ID and the notice?\nMan: Here you go. Sorry, I was out of town last week.\nWoman: No problem. Here''s your package. We hold them for fourteen days, so you came in time.\nMan: Good. Could I also buy some stamps?\nWoman: Of course. The stamps are at the next window."]', '["Purpose","Inference"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-021', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-021.mp3","test":"T3","qs":[{"stem":"What kind of permit does the man need?","opts":["A visitor permit","A commuter permit","A permit for campus residents","A one-day permit"]},{"stem":"How can the man pay for the permit?","opts":["By mailing a check","By adding it to his student account","By paying online only","By getting a discount from the dean"]}]}', '[1,1]', '["*you''ll need the commuter permit*. A — не упоминается; C — он живёт вне кампуса; D — не упоминается","*put it on my student account … that works too*. A — не упоминается; C — сказано: в кассе или на счёт; D — скидка не упоминается","Man: Hi, I need a parking permit for spring.\nWoman: Okay. Do you live on campus?\nMan: Off campus, about two miles away.\nWoman: Then you''ll need the commuter permit. It''s eighty dollars, payable at the cashier''s office.\nMan: Can I put it on my student account instead?\nWoman: Yes, that works too. Just fill out this form."]', '["Factual","Method"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-024', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-024.mp3","test":null,"qs":[{"stem":"What is the woman''s problem?","opts":["Her class starts too late","Her roommate studies too little","The room is too small","Music keeps her awake at night"]},{"stem":"What does the man agree to do?","opts":["Use headphones","Study at the library","Stop playing music completely","Wake up earlier"]}]}', '[3,0]', '["*the noise at night*; *after midnight*. A — у неё ранний урок; B — не обсуждается; C — не упоминается","*I''ll switch to headphones*. B — не предлагал; C — она не просила совсем; D — не упоминается","Woman: Hey, can we talk about the noise at night? I have an early class.\nMan: Sorry, I didn''t realize. I usually play music while I study.\nWoman: I don''t mind the music, but it''s after midnight. Could you use headphones?\nMan: Sure. I''d rather not wake you. I''ll switch to headphones starting tonight.\nWoman: Thanks. I really appreciate it."]', '["Main Idea","Factual"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-025', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-025.mp3","test":null,"qs":[{"stem":"Why does the woman mention the tutoring center?","opts":["To explain the drop deadline","To recommend a different course","To say tutors are expensive","To suggest an alternative to dropping the class"]},{"stem":"What will the man probably do next?","opts":["Visit the tutoring center","Drop chemistry on Friday","Switch to another major","Call his professor"]}]}', '[3,0]', '["*have you tried the tutoring center?* A — срок назван отдельно; B — другой курс не предлагается; C — услуга бесплатна","*I''ll go there tomorrow*. B — сначала репетитор; C — не упоминается; D — не упоминается","Man: I''m thinking about dropping my chemistry class. It''s much harder than I expected.\nWoman: The deadline to drop without a penalty is Friday. But have you tried the tutoring center?\nMan: No. I didn''t know they helped with chemistry.\nWoman: They do, and it''s free. If you still struggle after two weeks, we can talk again.\nMan: That sounds reasonable. I''ll go there tomorrow."]', '["Purpose","Inference"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-031', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-031.mp3","test":null,"qs":[{"stem":"What is the woman''s problem?","opts":["She cannot enter the science building","She was charged too much","She has lost her student ID","She missed the lost and found hours"]},{"stem":"What does the man need from the woman?","opts":["Another form of identification","Fifteen dollars in cash","A signed form from the dorm","A photo of the lost ID"]}]}', '[2,0]', '["*I think I lost my student ID*. A — нужен для общежития; B — цена приемлема; D — она уже проверила","*I just need to see another form of identification*. B — сумма названа, но не требуется сейчас; C — не упоминается; D — не упоминается","Woman: Hello, I think I lost my student ID somewhere in the science building.\nMan: Did you check the lost and found? It''s on the first floor.\nWoman: I did, but it wasn''t there. I need it to get into the dorm tonight.\nMan: In that case, I can issue a temporary pass for today. The new ID costs fifteen dollars and takes three days.\nWoman: Fifteen dollars is fine. Can I do both now?\nMan: Yes. I just need to see another form of identification."]', '["Main Idea","Factual"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-032', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-032.mp3","test":null,"qs":[{"stem":"Why does the man choose Monday?","opts":["Monday''s session is longer","He prefers morning sessions","He has a lab on Wednesday afternoon","The tutor is unavailable Wednesday"]},{"stem":"What does the woman ask the man to bring?","opts":["A list of formulas","His lab notes","A textbook","Examples from his homework"]}]}', '[2,3]', '["*I have a lab on Wednesday afternoon*. A — длительность не упоминается; B — время днём; D — у тьютора есть окно в среду","*bring a few examples from your homework*. A — формулы он знает; B — не упоминается; C — не упоминается","Man: I''d like to schedule a tutoring session for statistics, please.\nWoman: Of course. We have openings on Monday at two and Wednesday at four.\nMan: I have a lab on Wednesday afternoon. Is Monday possible?\nWoman: Yes, Monday at two. What would you like to focus on?\nMan: Probability. I understand the formulas, but I can''t apply them to word problems.\nWoman: Then bring a few examples from your homework, and we''ll work through them."]', '["Factual","Method"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-B-033', 'L', 'lco', 'B', '{"kind":"CONV","audio":"audio/L/CONV-033.mp3","test":null,"qs":[{"stem":"What is the woman''s main concern?","opts":["The experiments are too hard","Her lab partner does not prepare","The instructor is unfair","She is too busy with a job"]},{"stem":"What does the man suggest the woman do?","opts":["Do the experiments alone","Ask the instructor about changing partners","Quit the course","Tell her partner to find a job"]}]}', '[1,1]', '["*He never prepares for the experiments*. A — сложность не упоминается; C — к инструктору не претензий; D — работает партнёр","*talk to the instructor … switch partners*. A — не предлагает; C — не предлагает; D — не предлагает","Woman: I don''t think my lab partner and I are working well together. He never prepares for the experiments.\nMan: Have you talked to him about it?\nWoman: I tried, but he said he''s too busy with his job.\nMan: Then maybe talk to the instructor. She might let you switch partners.\nWoman: I don''t want to get him in trouble.\nMan: You wouldn''t be. You''d just be explaining that the arrangement isn''t working."]', '["Main Idea","Method"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-C-003', 'L', 'lco', 'C', '{"kind":"CONV","audio":"audio/L/CONV-003.mp3","test":"T1","qs":[{"stem":"What are the speakers mainly discussing?","opts":["Whether the woman should drop a class","How to prepare for a statistics exam","Why the tutoring center is closing","How to balance work and a group project"]},{"stem":"Why does the man mention statistics?","opts":["To explain why he changed his major","To suggest that economics is easier than statistics","To show that the tutoring center has helped him before","To warn the woman about another difficult class"]}]}', '[0,2]', '["B — статистика только пример; C — центр не закрывается; D — работа упомянута лишь как причина занятости","Подсказка: *They helped me a lot with statistics*. A, B, D — не сказано","Woman: I''m seriously thinking about dropping economics. The pace is just too fast.\nMan: Really? You did fine on the first midterm, didn''t you?\nWoman: Barely. And there are two more, plus a group project.\nMan: Well, before you decide, have you tried the tutoring center? They helped me a lot with statistics last year.\nWoman: I don''t know. Between work and my other classes, I''m not sure I can fit it in.\nMan: It''s only an hour a week. Honestly, I''d give it a month. If it''s still a struggle, then drop it.\nWoman: A month... Okay. That''s fair."]', '["Main Idea","Purpose"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-C-006', 'L', 'lco', 'C', '{"kind":"CONV","audio":"audio/L/CONV-006.mp3","test":"T1","qs":[{"stem":"What are the speakers mainly discussing?","opts":["Who should pay for cleaning supplies","How to divide the kitchen cleaning","Why the man is busy with lab reports","When to take out the trash"]},{"stem":"What does the man imply about the new arrangement?","opts":["He thinks it is completely fair","He would prefer to hire a cleaner","He plans to ask the woman to do more","He will accept it, though it gives him more work"]}]}', '[1,3]', '["A — деньги не обсуждаются; C и D — детали беседы","*That''s more days for me. But, alright…* — соглашается неохотно. A — слишком сильно; B, C — не сказано","Woman: Can we talk about the schedule for cleaning the kitchen? Last week, I did it three times.\nMan: Really? I thought I took out the trash on Tuesday and Thursday.\nWoman: Taking out the trash isn''t the same as cleaning. The counters, the sink, the floor?\nMan: Okay, fair. I guess I''ve been a little busy with my lab reports.\nWoman: I know you have. So how about we switch off? I''ll do Mondays and Wednesdays, and you do the rest?\nMan: That''s more days for me. But, alright, I can make that work."]', '["Main Idea","Inference"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-C-010', 'L', 'lco', 'C', '{"kind":"CONV","audio":"audio/L/CONV-010.mp3","test":"T2","qs":[{"stem":"Why does the man mention the exhibition in the library?","opts":["To invite the woman to submit a portfolio","To explain why the club needs new members","To show that phone photos can be successful","To suggest that the club prefers experienced photographers"]},{"stem":"What is the man''s attitude toward beginners?","opts":["He welcomes them","He thinks they need training before joining","He is worried about their equipment","He prefers that they wait until spring"]}]}', '[2,0]', '["*a couple of the best pictures were taken on phones*. A — портфолио не нужно; B — причина не называется; D — противоположно","*Honestly, that''s fine… Half of our members started that way*. B — противоречит *Nope*; C — оборудование не проблема; D — spring — прошлая выставка","Woman: Hi, are you the one who runs the photography club? I saw your poster.\nMan: That''s me. Are you thinking of joining?\nWoman: Maybe. I''m not very experienced, though. I just use my phone.\nMan: Honestly, that''s fine. Half of our members started that way. Last spring, we had an exhibition in the library, and a couple of the best pictures were taken on phones.\nWoman: Really? That''s encouraging. Do I need to show a portfolio?\nMan: Nope. Just come Thursday and bring any photo you like. We''ll talk about it."]', '["Purpose","Attitude"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-C-013', 'L', 'lco', 'C', '{"kind":"CONV","audio":"audio/L/CONV-013.mp3","test":"T2","qs":[{"stem":"What are the speakers mainly discussing?","opts":["Dividing sections of a report","Finding sources for an essay","Visiting cities for a project","Choosing a topic for a presentation"]},{"stem":"Why does the woman agree to the man''s topic?","opts":["The man has already found useful material","The professor approved water recycling","She prefers working alone","She learned that renewable energy is too popular"]}]}', '[3,0]', '["Выбирают тему: энергия или переработка воды. A — разделят разделы позже; B — источники — деталь; C — поездки не планируются","*if you''ve done that much research, I''m willing to try it*. B — преподаватель не упоминается; C — не упоминается; D — так сказал мужчина, а не она","Woman: I''ve been looking at the topic list for our presentation. I''m leaning toward renewable energy.\nMan: Hmm. Everybody picks that one. I was thinking about something less obvious, like water recycling in cities.\nWoman: That''s interesting, but I''m worried we won''t find enough sources.\nMan: I already found a few reports from three different cities.\nWoman: Oh. Well, if you''ve done that much research, I''m willing to try it.\nMan: Great. I''ll send you the links tonight, and we can split the sections tomorrow."]', '["Main Idea","Inference"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-C-017', 'L', 'lco', 'C', '{"kind":"CONV","audio":"audio/L/CONV-017.mp3","test":"T3","qs":[{"stem":"What does the professor imply about the woman''s lab report?","opts":["Its results were not explained enough","Its data was unreliable","Its predictions were incorrect","It was submitted late"]},{"stem":"Why does the professor say, \"They rarely do\"?","opts":["To criticize the woman''s data collection","To disagree that results are clear without explanation","To suggest that the woman has few results","To say that predictions are rarely correct"]}]}', '[0,1]', '["*the discussion section was thin… without explaining them*. B — данные названы сильными; C — прогнозы не обсуждаются; D — срок не упоминается","Отвечает на *numbers spoke for themselves*: числа редко говорят сами за себя. A — сбор данных не критикуется; C — результаты есть; D — прогнозы не оцениваются","Woman: Professor Ramirez, thanks for seeing me. I wanted to ask about the feedback on my lab report.\nMan: Of course. Your data was strong, but the discussion section was thin. You listed results without explaining them.\nWoman: I thought the numbers spoke for themselves.\nMan: They rarely do. A reader needs to know why a result matters, and whether it matches what you predicted.\nWoman: I see. If I revise it, could you look at it again?\nMan: Certainly. Bring it by on Friday, and we''ll go through it together."]', '["Inference","Attitude"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-C-020', 'L', 'lco', 'C', '{"kind":"CONV","audio":"audio/L/CONV-020.mp3","test":"T3","qs":[{"stem":"Why does the woman prefer the unpaid internship?","opts":["It is closer to campus","It offers a travel stipend","It could help her future applications","It lasts longer"]},{"stem":"What does the man suggest the woman do?","opts":["Buy a car before she decides","Accept both internships","Ask the company for help with travel costs","Choose the better-paid offer"]}]}', '[2,2]', '["*a good reference… graduate school*. A — близость относится к другому; B — стипендия — предложение мужчины; D — длительность не упоминается","*ask the unpaid company for a small travel stipend*. A — машина — проблема, а не совет; B — обе нельзя принять; D — он не советует это","Woman: I got two internship offers. One pays well but is far away. The other is unpaid, but it''s with a company I admire.\nMan: Tough choice. What do you want out of the experience?\nWoman: Honestly, a good reference. If I''m going to apply to graduate school, that would matter more than money.\nMan: Then it sounds like you''ve decided. Though you''d need a car for the first one.\nWoman: Right, and I don''t have one. That''s the part that worries me.\nMan: Maybe ask the unpaid company for a small travel stipend. People are often more flexible than you''d expect."]', '["Purpose","Method"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-C-026', 'L', 'lco', 'C', '{"kind":"CONV","audio":"audio/L/CONV-026.mp3","test":null,"qs":[{"stem":"What is the woman''s main concern?","opts":["The research is not accurate","The man''s section is too long for the time limit","The professor dislikes appendices","The man has not finished his work"]},{"stem":"What does the man''s comment, \"Cutting it hurts, though,\" suggest?","opts":["He is angry at the woman","He is reluctant to shorten his work","He believes the section is perfect","He wants to leave the group"]}]}', '[1,1]', '["*we only have ten minutes*. A — исследование названо хорошим; C — не упоминается; D — он закончил","*I spent a week on that*; неохота сокращать. A — не злится, соглашается; C — не говорит; D — не упоминается","Woman: I looked over your section of the presentation. The research is good, but it''s too long.\nMan: I thought more detail would impress the professor.\nWoman: Maybe, but we only have ten minutes. If you cut it in half, we can fit in the other sections.\nMan: Cutting it hurts, though. I spent a week on that.\nWoman: I get that. Keep the extra material in an appendix, so nothing is wasted.\nMan: Fine. That''s a fair compromise."]', '["Main Idea","Attitude"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-C-027', 'L', 'lco', 'C', '{"kind":"CONV","audio":"audio/L/CONV-027.mp3","test":null,"qs":[{"stem":"Why does the professor ask for the outline?","opts":["To grade it separately","To make sure the student is making progress","To decide whether the student was sick","To change the paper''s topic"]},{"stem":"What does the professor imply in her last statement?","opts":["She dislikes extensions","She expects a perfect paper","She prefers quality work to quick work","She wants the paper tomorrow"]}]}', '[1,2]', '["*only if you send me your outline today*. A — не оценивается; C — болезнь не проверяется; D — тема не меняется","*I''d rather help you finish well than … a rushed paper*. A — она дала продление; B — не требует идеала; D — срок +2 дня","Man: Professor Dunn, I wanted to ask about extending the deadline for my research paper.\nWoman: May I ask why? You''ve had three weeks.\nMan: I was sick last week, and my sources arrived late from interlibrary loan.\nWoman: I see. I can give you two more days, but only if you send me your outline today.\nMan: That''s fair. I''ll send it right after this meeting.\nWoman: Good. I''d rather help you finish well than receive a rushed paper."]', '["Purpose","Inference"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-C-034', 'L', 'lco', 'C', '{"kind":"CONV","audio":"audio/L/CONV-034.mp3","test":null,"qs":[{"stem":"Why does the professor mention that all three topics involve how cities use land?","opts":["To suggest that the topics are too broad","To explain why farming is more important","To help the student find a common focus","To criticize the student''s choices"]},{"stem":"What will the student probably do before the next meeting?","opts":["Write a short proposal","Change her major","Visit an urban farm","Choose a different professor"]}]}', '[2,0]', '["*all three involve how cities use land*; поиск общей темы. A — не критикует широту; B — не сравнивает; D — одобряет","*Sketch a one-page proposal*. B — не упоминается; C — не упоминается; D — не упоминается","Woman: Professor Allen, I''m struggling to narrow down my thesis topic. There are so many things I find interesting.\nMan: That''s common. What are the two or three that excite you most?\nWoman: Urban farming, food waste, and how cities plan green space.\nMan: Interesting. Notice that all three involve how cities use land. Perhaps your question could focus on that.\nWoman: So, something like how urban farms change neighborhoods?\nMan: Exactly. Sketch a one-page proposal, and we''ll refine it next week."]', '["Purpose","Inference"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-C-035', 'L', 'lco', 'C', '{"kind":"CONV","audio":"audio/L/CONV-035.mp3","test":null,"qs":[{"stem":"What does the woman suggest about moving off campus?","opts":["It may be more expensive than the man expects","It is always cheaper than dorms","It is impossible for first-year students","It is better for studying"]},{"stem":"What does the man mean when he says, \"I value independence more than convenience\"?","opts":["He wants to live alone","He thinks the dorms are convenient","He has already signed a lease","He is willing to accept some inconvenience to live freely"]}]}', '[0,3]', '["*Rent plus a bus pass could cost more than a dorm*. B — не утверждается; C — не упоминается; D — она ценит библиотеку рядом","Свобода важнее удобства. A — он собирается жить с друзьями; B — он говорит, что общежитие ограничивает; C — договор не подписан","Man: I''m leaning toward moving off campus next year. The dorms are so restrictive.\nWoman: True, but have you thought about transportation? Rent plus a bus pass could cost more than a dorm.\nMan: I''d split an apartment with two friends, so rent would be lower.\nWoman: That helps. Still, I''d miss being steps from the library. I do my best work there.\nMan: I guess I value independence more than convenience.\nWoman: Fair enough. Just run the numbers before you sign anything."]', '["Inference","Attitude"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-CONV-C-036', 'L', 'lco', 'C', '{"kind":"CONV","audio":"audio/L/CONV-036.mp3","test":null,"qs":[{"stem":"Why hasn''t the woman been assigned a job?","opts":["All positions were filled","Her application is missing a signature","She applied after the deadline","She is not eligible"]},{"stem":"What will the man probably do after receiving the signature?","opts":["Reject her application","Cancel her award","Ask her to apply again","Process her application quickly"]}]}', '[1,3]', '["*it''s incomplete. You need your supervisor''s signature*. A — он сказал «многие»; её заявка просто неполна; C — она подала в первый день; D — право есть","*I''ll flag your file so it''s processed quickly*. A — не упоминается; B — не упоминается; C — не упоминается","Woman: I''m calling about my work-study award. I haven''t been assigned a job yet, and the semester started two weeks ago.\nMan: I see. Work-study positions are filled on a first-come basis, so many have been taken.\nWoman: I applied on the first day, though.\nMan: Then your application may still be under review. Let me check. Yes, it''s incomplete. You need your supervisor''s signature.\nWoman: I didn''t realize I needed one. Can I send it today?\nMan: Yes, and I''ll flag your file so it''s processed quickly."]', '["Factual","Inference"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-A-002', 'L', 'lcr', 'A', '{"kind":"LCR","audio":"audio/L/LCR-002.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Yes, it''s always crowded on weekends.","I think it''s at ten, but let me check.","I closed my account yesterday.","No, I didn''t borrow that book."]}]}', '[1]', '["- A — отвечает «Yes» на вопрос о времени и уходит в другую тему (толпа)\n- C — *closes → closed*: повтор слова без связи\n- D — отвечает на вопрос про книгу","Do you know what time the library closes tonight?"]', '["Choose a Response"]', -1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-A-003', 'L', 'lcr', 'A', '{"kind":"LCR","audio":"audio/L/LCR-003.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["No, please go ahead.","Yes, I take the bus every day.","It''s taken me an hour to finish.","Thanks, I already ate."]}]}', '[0]', '["- B — *taken → take*: звуковая ловушка\n- C — *taken* в другом значении (потребовалось время)\n- D — не связано с вопросом","Excuse me, is this seat taken?"]', '["Choose a Response"]', -1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-A-004', 'L', 'lcr', 'A', '{"kind":"LCR","audio":"audio/L/LCR-004.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Yes, the cafeteria opens at seven.","I''ll fast for the whole week.","It''s a very long way to campus.","I know. It feels like it just started."]}]}', '[3]', '["- A — *Yes* и тема столовой: нет связи\n- B — *fast* в значении «поститься»\n- C — *how fast → long way*: тема расстояния вместо времени","I can''t believe how fast this semester went."]', '["Choose a Response"]', -1, 'pretest', 1793553157228, 1793553157228)
