INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-A-013', 'L', 'lcr', 'A', '{"kind":"LCR","audio":"audio/L/LCR-013.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Yes, I got a high grade on the exam.","Sure, come in and have a seat.","A minute ago, in the hallway.","Of course not. The grade was posted online."]}]}', '[1]', '["- A — *grade* повторено, но вопрос о разговоре не услышан\n- C — *minute* повторено: ответ на вопрос «когда»\n- D — *Of course not* отвечает «нет» на просьбу, где ждут согласия","Do you have a minute to talk about my grade?"]', '["Choose a Response"]', -1, 'pretest', 1793553157228, 1793553157228)
