INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-A-014', 'L', 'lcr', 'A', '{"kind":"LCR","audio":"audio/L/LCR-014.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Yes, I''d love to listen to it.","I turned it up because it''s my favorite song.","The music class starts at nine.","Oh, sorry. I didn''t realize it was so loud."]}]}', '[3]', '["- A — *Yes* к «Would you mind» значит «да, возражаю»; ответ не по смыслу\n- B — грубо и не решает просьбу\n- C — *music* повторено, тема другая","Would you mind turning down the music a little?"]', '["Choose a Response"]', -1, 'pretest', 1793553157228, 1793553157228)
