INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-A-015', 'L', 'lcr', 'A', '{"kind":"LCR","audio":"audio/L/LCR-015.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["That sounds fun. When do they meet?","Yes, the club joined us last week.","I think you should have stayed home.","No, I haven''t thought about it."]}]}', '[0]', '["- B — *club, join* повторены, но смысл нарушен\n- C — неуместный совет, время глагола не подходит\n- D — отвечает «нет» на утверждение, а не на вопрос","I''m thinking about joining the hiking club."]', '["Choose a Response"]', -1, 'pretest', 1793553157228, 1793553157228)
