INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-A-025', 'L', 'lcr', 'A', '{"kind":"LCR","audio":"audio/L/LCR-025.mp3","test":"T2","qs":[{"stem":"Choose the best response.","opts":["Sure, I''ll send you a copy tonight.","I borrowed them from the library.","Monday is my busiest day.","The notes are very helpful."]}]}', '[0]', '["- B — прошедшее время и другой источник\n- C — *Monday* повторено, но на просьбу не отвечает\n- D — *notes* повторено, но нет ни согласия, ни отказа","Could I borrow your notes from Monday?"]', '["Choose a Response"]', -1, 'pretest', 1793553157228, 1793553157228)
