INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-B-001', 'L', 'lcr', 'B', '{"kind":"LCR","audio":"audio/L/LCR-001.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["No problem, I''ll give them back tomorrow.","Yes, Monday works better for me.","Sorry, I missed that class too.","I bought a new notebook on Monday."]}]}', '[2]', '["Отвечающий не может дать конспект, потому что сам пропустил занятие: косвенный, но уместный ответ на вежливую просьбу.\n\n- A — реплика того, кто берёт конспект, а не того, кто его даёт (смена ролей).\n- B — подхватывает слово *Monday*, но отвечает на предложение встретиться.\n- D — повтор *notes / Monday* без связи с просьбой.\n\nЛовушка для русскоязычных: *Would you mind…?* — ответ «Yes» означает «против».","Would you mind if I borrowed your notes from Monday?"]', '["Choose a Response"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-B-005', 'L', 'lcr', 'B', '{"kind":"LCR","audio":"audio/L/LCR-005.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["I''m not sure which chemistry book to buy.","Not yet. The online system was down yesterday.","Yes, I''ll register after the lab.","The lab report is due next week."]}]}', '[1]', '["- A — повтор *chemistry*, но тема учебника\n- C — *Yes* + будущее время: противоречие (если зарегистрирован, не «зарегистрируюсь»)\n- D — *lab* повторено, ответа на вопрос нет","Haven''t you registered for the chemistry lab yet?"]', '["Choose a Response"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-B-006', 'L', 'lcr', 'B', '{"kind":"LCR","audio":"audio/L/LCR-006.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Yes, my essay is about economics.","Sure, I read it yesterday.","I''d like to, but I''m busy until six.","It''s tonight at seven."]}]}', '[2]', '["- A — *essay* повторено, просьба не обработана\n- B — прошедшее время вместо согласия на будущее действие\n- D — *tonight* повторено, о времени никто не спрашивал","I was hoping you could proofread my essay before tonight."]', '["Choose a Response"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-B-007', 'L', 'lcr', 'B', '{"kind":"LCR","audio":"audio/L/LCR-007.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["I wouldn''t count on it.","I handed it in on time.","Yes, she extended her office hours.","She teaches on Tuesdays and Thursdays."]}]}', '[0]', '["- B — отвечает про сдачу, а не про прогноз\n- C — *extend* повторено: ловушка по слову\n- D — информация о расписании, не ответ","Do you think the professor will extend the deadline?"]', '["Choose a Response"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-B-008', 'L', 'lcr', 'B', '{"kind":"LCR","audio":"audio/L/LCR-008.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Because the exam is on Monday.","I''ll have a coffee, please.","Yes, I got a library card last year.","Good idea. It''s too quiet in the library."]}]}', '[3]', '["- A — *Why don''t we…?* — предложение, а не вопрос о причине; «Because» не подходит\n- B — ассоциация *café → coffee*\n- C — *library* повторено: нет связи с предложением","Why don''t we study at the café instead of the library?"]', '["Choose a Response"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-B-009', 'L', 'lcr', 'B', '{"kind":"LCR","audio":"audio/L/LCR-009.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Yes, I canceled my subscription.","The lecture hall is down the hall.","So did I. I almost stayed home.","No, he lectured yesterday."]}]}', '[2]', '["- A — *canceled* повторено в другом значении\n- B — *lecture* повторено: ответ про место\n- D — путаница в роде/времени: преподаватель не обсуждался","I thought the lecture would be canceled today."]', '["Choose a Response"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-B-016', 'L', 'lcr', 'B', '{"kind":"LCR","audio":"audio/L/LCR-016.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Yes, the bus is usually late.","I showed you the schedule yesterday.","No worries. We''ve only just started.","Thanks for the ride."]}]}', '[2]', '["- A — соглашается про автобус, но не реагирует на извинение\n- B — *showed* похоже на *showed up*, но смысл другой\n- D — благодарность за поездку, которой не было","Sorry I''m late. The bus never showed up."]', '["Choose a Response"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-B-017', 'L', 'lcr', 'B', '{"kind":"LCR","audio":"audio/L/LCR-017.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Yes, I could register tomorrow.","It''s on the second floor, past the cafeteria.","I''m not an office worker.","It was open until five o''clock."]}]}', '[1]', '["- A — *register* похоже на *registrar*, но вопрос о месте\n- C — не отвечает на просьбу\n- D — прошедшее время и время работы вместо места","Could you tell me where the registrar''s office is?"]', '["Choose a Response"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-B-019', 'L', 'lcr', 'B', '{"kind":"LCR","audio":"audio/L/LCR-019.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["No, it''s night now.","I worked there for a year.","I have. I''m hoping to finish it by morning.","Yes, you should have called me."]}]}', '[2]', '["- A — формально «No», но бессмысленно\n- B — *worked* повторено, но речь о другом месте и сроке\n- D — неуместный упрёк","You''ve been working on that project all night, haven''t you?"]', '["Choose a Response"]', 0, 'pretest', 1793553157228, 1793553157228)
