INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-B-020', 'L', 'lcr', 'B', '{"kind":"LCR","audio":"audio/L/LCR-020.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Better than I expected, actually.","I interviewed him on Tuesday.","It went to the career center.","Yes, I will go tomorrow."]}]}', '[0]', '["- B — *interview* повторено: рассказ о том, кого он интервьюировал\n- C — *went* повторено буквально\n- D — «Yes» не подходит к вопросу «How», и время не то","How did your interview go?"]', '["Choose a Response"]', 0, 'pretest', 1793553157228, 1793553157228)
