INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-010', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-010.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Yes, it''s a long way from here.","I''m sorry. I should have texted you.","The lab was closed for renovations last year.","I would have come too, if you''d asked."]}]}', '[1]', '["- A — *way* повторено: соглашается с расстоянием, а не с жалобой\n- C — *closed* повторено: другой год\n- D — *would have come*: грамматика повторена, смысл не подходит","If I''d known the lab was closed, I wouldn''t have come all the way here."]', '["Choose a Response"]', 1, 'pretest', 1793553157228, 1793553157228)
