INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-011', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-011.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Both buildings are on the east side.","Yes, I decided yesterday.","I majored in biology last year.","Why not take an introductory course in each?"]}]}', '[3]', '["- A — упоминает здания, а не выбор\n- B — *decide → decided* + *Yes* на не-вопрос\n- C — *biology* повторено: рассказ о себе вместо совета","I can''t decide whether to major in biology or psychology."]', '["Choose a Response"]', 1, 'pretest', 1793553157228, 1793553157228)
