INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-012', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-012.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Maybe something came up.","Yes, the seminar starts at two.","I don''t like late classes either.","No, I wasn''t invited to the seminar."]}]}', '[0]', '["- B — *seminar* повторено: время начала, а не причина опоздания\n- C — *late* повторено: личное предпочтение\n- D — *seminar* повторено: приглашение не обсуждалось","It''s not like Dr. Chen to be late for her own seminar."]', '["Choose a Response"]', 1, 'pretest', 1793553157228, 1793553157228)
