INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-018', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-018.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["Yes, the chance is on Friday.","The extended library hours are posted.","I didn''t know you had a deadline.","I wouldn''t count on it, but you can ask."]}]}', '[3]', '["- A — *chance* повторено, ответ бессмыслен\n- B — *extended* повторено, но про библиотеку\n- C — не отвечает на вопрос и звучит странно","Is there any chance the deadline will be extended?"]', '["Choose a Response"]', 1, 'pretest', 1793553157228, 1793553157228)
