INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-021', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-021.mp3","test":"T1","qs":[{"stem":"Choose the best response.","opts":["I''m sorry you were late to the library.","It stays on the second floor.","I wish you luck on your weekend.","Me too. I always run out of time on Saturdays."]}]}', '[3]', '["- A — *library* повторено, но смысл не связан\n- B — *stays* повторено, но речь о месте\n- C — *wish* повторено, но это другая речевая функция","I wish the library stayed open later on weekends."]', '["Choose a Response"]', 1, 'pretest', 1793553157228, 1793553157228)
