INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-027', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-027.mp3","test":"T2","qs":[{"stem":"Choose the best response.","opts":["Yes, I happened to know them.","I wouldn''t leave without a coat.","Try the front desk. Someone may have turned them in.","They are not locked, I believe."]}]}', '[2]', '["- A — *happen to know* искажено\n- B — *wouldn''t* повторено, тема другая\n- D — *locked* похоже на keys, но не отвечает","You wouldn''t happen to know where I left my keys, would you?"]', '["Choose a Response"]', 1, 'pretest', 1793553157228, 1793553157228)
