INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-030', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-030.mp3","test":"T2","qs":[{"stem":"Choose the best response.","opts":["Quiet is the best kind of room.","The trek was shorter than I thought.","It costs five dollars to park.","Honestly, it''s the only place I can focus."]}]}', '[3]', '["- A — *quiet* повторено, нет позиции\n- B — *trek* повторено, но прошедшее время\n- C — информация о парковке не по теме","I''m not sure the library''s quiet room is worth the trek."]', '["Choose a Response"]', 1, 'pretest', 1793553157228, 1793553157228)
