INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-031', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-031.mp3","test":"T2","qs":[{"stem":"Choose the best response.","opts":["Yes, the lecturer is longer.","I thought so, but I was wrong about the weather.","Me too. Usually he goes right up to the end.","The professor would have thought so."]}]}', '[2]', '["- A — сравнение вместо согласия\n- B — *thought* повторено, тема другая\n- D — эхо грамматики, смысл не связан","I''d have thought the lecture would run longer."]', '["Choose a Response"]', 1, 'pretest', 1793553157228, 1793553157228)
