INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-040', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-040.mp3","test":"T2","qs":[{"stem":"Choose the best response.","opts":["It''s the same for me, thanks.","Present? I haven''t received a gift.","Sure, you can present it to the first.","No problem. I''ll go first."]}]}', '[3]', '["- A — *same* повторено, не реагирует на просьбу\n- B — *present* как «подарок» — неверное значение\n- C — *present / first* повторены без смысла","I''d rather not present first, if it''s all the same to you."]', '["Choose a Response"]', 1, 'pretest', 1793553157228, 1793553157228)
