INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-041', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-041.mp3","test":"T2","qs":[{"stem":"Choose the best response.","opts":["Pushed back? Does your back hurt?","Yes, the week was pushed to the deadline.","Really? That''s a relief. I haven''t started.","I apparently finished early."]}]}', '[2]', '["- A — неверное понимание идиомы\n- B — путает слова местами\n- D — *apparently* повторено, неуместное утверждение","Apparently, the deadline''s been pushed back a week."]', '["Choose a Response"]', 1, 'pretest', 1793553157228, 1793553157228)
