INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-054', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-054.mp3","test":"T3","qs":[{"stem":"Choose the best response.","opts":["I know. I always have to sit by the window to charge my laptop.","Yes, they think about the library.","The outlets are made of plastic.","I''d rather have a quiet room."]}]}', '[0]', '["- B — игра слов *think*\n- C — описание материала\n- D — уход от темы","You''d think they''d have more outlets in this library."]', '["Choose a Response"]', 1, 'pretest', 1793553157228, 1793553157228)
