INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-LCR-C-118', 'L', 'lcr', 'C', '{"kind":"LCR","audio":"audio/L/LCR-118.mp3","test":null,"qs":[{"stem":"Choose the best response.","opts":["Yes, I swore at the table.","I left the desk at noon.","Maybe someone turned it in at the front desk.","I could have been wrong."]}]}', '[2]', '["- A — *swear* в другом смысле\n- B — не помогает найти\n- D — не реагирует","I could have sworn I left my notebook on this table."]', '["Choose a Response"]', 1, 'active', 1793553157228, 1793553157228)
