INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-B-001', 'L', 'lat', 'B', '{"kind":"TALK","audio":"audio/L/TALK-001.mp3","test":"T1","qs":[{"stem":"What is the talk mainly about?","opts":["How streetlights affect the migration of birds","Why some birds in cities have started singing at night","Differences between European robins and other birds","Ways to reduce traffic noise in urban areas"]},{"stem":"Why does the speaker mention a loud concert?","opts":["To show that noise can damage birds'' hearing","To suggest that birds prefer music to traffic","To describe where a study of robins took place","To explain how birds respond to noise by changing when they sing"]},{"stem":"According to the speaker, what did researchers find about robins in noisy neighborhoods?","opts":["They sang at night more often, even where light levels were similar.","They stopped singing during the day altogether.","They sang at a higher pitch than robins in quiet areas.","They were attracted to brightly lit streets."]},{"stem":"What is the speaker''s attitude toward the ability of birds to adapt to city noise?","opts":["He is confident that all species will eventually adjust.","He believes streetlights are a more serious problem than noise.","He doubts that many species will be able to adjust.","He is unconcerned because robins are coping well."]}]}', '[1,3,0,2]', '["A — миграция не обсуждается; C — малиновки лишь пример исследования; D — способов снижения шума нет","Аналогия «перекричать или дождаться тишины» объясняет, почему птицы ждут. A, B — не сказано; C — концерт не место исследования","B — преувеличение (*shift* ≠ полностью перестали); C — высота голоса упомянута только в конце и о других видах; D — свет «играет роль», но вывод другой","Маркеры: *But honestly, I''m not convinced… may simply go quiet*. A — противоположно; B — не сравнивает; D — *So far… coping* тут же опровергается словом *But*","So, if you live in a city, you may have noticed something a bit odd: birds singing in the middle of the night. A lot of people assume it''s the streetlights, that the birds think it''s morning. And, well, light does play a part. But researchers studying European robins found something more interesting. In noisy neighborhoods, robins sang at night far more often than in quiet ones, even where the light levels were the same. Why? Think of trying to talk to a friend at a loud concert. You can shout, or you can wait until the music stops. The robins, it seems, are waiting. During the day, traffic noise drowns out their songs, so they shift their singing to the quieter hours, when other birds can actually hear them. Now, this isn''t free. A bird that''s up singing at three in the morning is losing sleep, and it''s burning energy it could be using to find food. So far, robins seem to be coping. But honestly, I''m not convinced every species can adjust this easily. Birds that can''t change when they sing, or, um, how high they sing, may simply go quiet in our cities. And that''s something we''re only just beginning to measure."]', '["Main Idea","Purpose","Factual","Attitude"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-B-003', 'L', 'lat', 'B', '{"kind":"TALK","audio":"audio/L/TALK-003.mp3","test":"T1","qs":[{"stem":"What is the talk mainly about?","opts":["How Roman roads were built and what they led to","Why modern roads are better than ancient ones","How Rome defeated rival empires","The cost of building the Roman army"]},{"stem":"According to the professor, why were Roman roads built in layers?","opts":["So that soldiers could march more quietly","So that the stones would be easier to repair","So that merchants could carry heavier goods","So that water could drain away and the road would last"]},{"stem":"Why does the professor mention soldiers?","opts":["To argue that the army controlled the economy","To show that soldiers also worked as merchants","To explain the original reason the roads were built","To describe how roads were repaired"]},{"stem":"What does the professor imply about the Roman roads?","opts":["They were never used for trade","They were too expensive to maintain","They were built mostly for ordinary travelers","They had effects their builders probably did not plan"]}]}', '[0,3,2,3]', '["B, C, D — не обсуждаются","*Water could drain away, which kept the road from falling apart*. A, B, C — не сказано","*the roads were first built for soldiers*. A, B, D — не сказано","*a project built for military reasons ended up changing the whole economy*. A — противоположно; B, C — не сказано","Today I want to talk about something we usually take for granted: roads. In particular, the roads of the Roman Empire. When we think of Rome, we often think of the army, or the Colosseum, but the road network may have been just as important. The Romans built tens of thousands of kilometers of paved roads, and parts of some of them are still visible today. So how did they do it? Well, a Roman road wasn''t just a layer of stones. Builders dug a trench and filled it in layers: large stones at the bottom, then gravel, and finally a smooth surface on top. Water could drain away, which kept the road from falling apart. Now, the roads were first built for soldiers, so that the army could move quickly to any trouble spot. But here''s the interesting part. Once the roads existed, merchants started using them too, and so did ordinary travelers. Towns grew up along the major routes, and goods, ideas, even languages spread much faster than before. In other words, a project built for military reasons ended up changing the whole economy. For next class, think of a modern example of something that started with one purpose and ended up serving another."]', '["Main Idea","Factual","Purpose","Inference"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-B-006', 'L', 'lat', 'B', '{"kind":"TALK","audio":"audio/L/TALK-006.mp3","test":"T2","qs":[{"stem":"What is the talk mainly about?","opts":["How octopuses protect themselves","Why octopus arms can grow back","Evidence that octopuses are intelligent","The differences between octopuses and dogs"]},{"stem":"Where are most of an octopus''s neurons?","opts":["In its head","In its eyes","Along its backbone","In its arms"]},{"stem":"How did researchers test octopus intelligence?","opts":["By comparing brain sizes","By giving them problems to solve","By measuring how quickly they grow","By training them to perform in front of audiences"]},{"stem":"What is the professor''s attitude toward octopus intelligence?","opts":["She is interested but cautious about comparing it to human thinking","She is certain it equals human intelligence","She is skeptical about the research","She thinks it is not worth studying"]}]}', '[2,3,1,0]', '["Весь рассказ — о признаках интеллекта осьминогов. A — защита не обсуждается; B — регенерация не упоминается; D — собаки не упоминаются","*About two thirds … are in its arms*. A — противоположно; B — не упоминается; C — у осьминога нет позвоночника","*researchers give them problems to solve*: банка, лабиринты. A — размер мозга — не метод проверки; C — рост не упоминается; D — не упоминается","*we shouldn''t assume an octopus thinks the way we do. Still, I find it fascinating*. B — противоположно; C — противоположно; D — противоположно","Today I''d like to talk about an animal that surprises many scientists: the octopus. For a long time, people thought invertebrates, animals without a backbone, couldn''t be very smart. But octopuses have changed that view. An octopus has roughly five hundred million neurons, far more than most invertebrates. What''s unusual is where they are. About two thirds of an octopus''s neurons are in its arms, not in its head. That means each arm can make some decisions on its own, like how to touch or grab something. Now, how do we know octopuses are intelligent? Well, researchers give them problems to solve. In one famous test, an octopus was placed in a clear jar with the lid screwed on. After a short time, it figured out how to unscrew the lid and escape. Others have learned to find their way through mazes and even to recognize individual people. Of course, intelligence is hard to measure, and we shouldn''t assume an octopus thinks the way we do. Still, I find it fascinating that such a different kind of nervous system can solve complex problems. For your next assignment, I''d like you to compare octopus intelligence with that of a bird of your choice."]', '["Main Idea","Factual","Method","Attitude"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-B-008', 'L', 'lat', 'B', '{"kind":"TALK","audio":"audio/L/TALK-008.mp3","test":"T2","qs":[{"stem":"What is the talk mainly about?","opts":["Why people avoid busy sidewalks","How the presence of others affects helping behavior","How to design psychology experiments","Why emergencies are rare"]},{"stem":"According to the professor, what is diffusion of responsibility?","opts":["Each person assuming someone else will act","People refusing to talk during emergencies","One person taking responsibility for everyone","Responsibility shifting to the police"]},{"stem":"How did researchers study the bystander effect in the experiment?","opts":["They placed students in a real emergency","They interviewed people on sidewalks","They compared students of different ages","They changed how many people participants believed were listening"]},{"stem":"What does the professor imply about asking one specific person for help?","opts":["It is rude in an emergency","It works only in small groups","It is unnecessary when danger is clear","It can make people more likely to act"]}]}', '[1,0,3,3]', '["Определение *bystander effect* и опыт. A — не обсуждается; C — опыт — пример, не тема; D — не обсуждается","*Each person thinks, ''Someone else will do something.''* B — не упоминается; C — противоположно; D — не упоминается","*only listener* против *four other people*. A — авария была сымитирована; B — опрос не упоминается; C — возраст не сравнивался","*a simple step can change the outcome: pick one person and ask directly*. A — противоположно; B — не сказано; C — не то, что она подразумевает","Imagine you see someone drop their books and fall on a busy sidewalk. Would you stop to help? Most of us would say yes. But psychologists have found that the answer depends on who else is around. This is called the bystander effect: the more people who witness an emergency, the less likely any one of them is to help. In a famous experiment in the nineteen sixties, researchers asked students to talk over an intercom. During the conversation, one student seemed to have a medical emergency. When participants believed they were the only listener, most of them quickly went for help. When they believed four other people were listening, far fewer did. Why? Researchers suggest a main reason is diffusion of responsibility. Each person thinks, \"Someone else will do something.\" Another reason is that people look at others to decide whether a situation is serious. If everyone stays calm, everyone assumes things are fine. Now, this doesn''t mean people are cold-hearted. In fact, when emergencies are clear and dangerous, people often act. What it tells us is that a simple step can change the outcome: pick one person and ask directly, \"You, in the blue jacket, call an ambulance.\""]', '["Main Idea","Factual","Method","Inference"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-B-010', 'L', 'lat', 'B', '{"kind":"TALK","audio":"audio/L/TALK-010.mp3","test":"T3","qs":[{"stem":"What is the talk mainly about?","opts":["Why leaves change color in autumn","How trees make food in the summer","Why some trees lose their leaves earlier","How scientists measure sunlight"]},{"stem":"According to the professor, why do leaves look yellow or orange in autumn?","opts":["The tree begins to make new yellow pigments","Chlorophyll turns into carotenoids","Carotenoids that were hidden by chlorophyll become visible","Cool nights damage the green pigment"]},{"stem":"Why does the professor mention sunscreen?","opts":["To show how scientists protect leaves in experiments","To describe how trees absorb nutrients","To explain a possible function of red pigments","To compare summer and autumn weather"]},{"stem":"What can be inferred about the brightest red leaves?","opts":["They appear only on very old trees","They are more likely after sunny days and cool nights","They are produced in summer","They fall earlier than yellow leaves"]}]}', '[0,2,2,1]', '["Вся лекция объясняет осенние цвета листьев. B — лишь фон; C — сроки листопада не обсуждаются; D — измерение света не упоминается","*They are simply hidden… The green fades*. A — жёлтые пигменты были всегда; B — превращение не упоминается; D — повреждения не упоминаются","*the red acts like sunscreen, protecting the leaf*. A — эксперименты не упоминаются; B — питательные вещества — другая функция; D — погода не сравнивается","*the brightest reds appear after sunny days and cool nights*. A — возраст не упоминается; C — красный не летом; D — опадение не сравнивается","Every autumn, forests across the world turn red, orange, and gold. Today I''d like to explain why. Leaves are green because of chlorophyll, a pigment that captures sunlight for photosynthesis. All summer, the tree keeps making fresh chlorophyll, so green dominates. But there are other pigments in the leaf the whole time. Carotenoids, for example, produce yellow and orange. They are simply hidden. When days get shorter and temperatures drop, the tree stops making chlorophyll. The green fades, and the yellow and orange appear. Now, red is a different story. Red pigments, called anthocyanins, are not present in summer. The tree actually makes them in autumn, when sugars get trapped in the leaf. Scientists once thought this was just a side effect. Now some believe the red acts like sunscreen, protecting the leaf while the tree pulls valuable nutrients back into its branches. This helps explain why the brightest reds appear after sunny days and cool nights. So, the next time you see a red maple, remember that you are looking at a tree that is working hard right up until the leaf falls. Next week, we will discuss how trees prepare for winter."]', '["Main Idea","Factual","Purpose","Inference"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-B-012', 'L', 'lat', 'B', '{"kind":"TALK","audio":"audio/L/TALK-012.mp3","test":"T3","qs":[{"stem":"What is the talk mainly about?","opts":["How businesses make a profit","Why people prefer to spend money","The idea that every choice has a hidden cost","How to plan a budget"]},{"stem":"In the professor''s example, what is the opportunity cost of going hiking?","opts":["The cost of snacks","The time spent with friends","The price of hiking equipment","The money from the job"]},{"stem":"Why does the professor mention sleep?","opts":["To explain why students should study less","To compare work and rest","To describe a business decision","To show that opportunity cost is not always about money"]},{"stem":"What will students probably do before the next class?","opts":["Identify the opportunity cost of one of their choices","Write a report about a restaurant","Calculate the cost of a hiking trip","Compare two business plans"]}]}', '[2,3,3,0]', '["Определение opportunity cost и примеры. A — прибыль не обсуждается; B — траты не главная тема; D — бюджет не обсуждается","*It is the eighty dollars you could have earned*. A — еда — не альтернатива; B — друзья не потеря; C — снаряжение не упоминается","*not always about money … the sleep you lose*. A — не советует учиться меньше; B — работа не сравнивается; C — бизнес — другой пример","*think of one choice … identify its opportunity cost*. B — ресторан — пример; C — поход — пример; D — планы не упоминаются","Today we are going to talk about opportunity cost, one of the most useful ideas in economics. Opportunity cost is simple to define. It is the value of the best alternative you give up when you make a choice. Let me give an example. Suppose you have a free Saturday. You can work at a part-time job and earn eighty dollars, or you can go hiking with friends. If you choose hiking, the opportunity cost is not the money you spend on snacks. It is the eighty dollars you could have earned. Notice that opportunity cost is not always about money. If you study for an exam instead of sleeping, the cost is the sleep you lose. Businesses think this way, too. A company that uses its building for a restaurant gives up the rent it could earn from a store. Economists say that every choice has a cost, even when no one asks you to pay. Understanding this idea helps us make better decisions, because it forces us to compare what we gain with what we lose. For our next class, think of one choice you made this week and identify its opportunity cost."]', '["Main Idea","Factual","Purpose","Inference"]', 0, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-B-014', 'L', 'lat', 'B', '{"kind":"TALK","audio":"audio/L/TALK-014.mp3","test":null,"qs":[{"stem":"What is the talk mainly about?","opts":["How the Moon was formed","Why the Earth rotates","How beaches change over time","What causes ocean tides"]},{"stem":"According to the professor, why is there a second high tide on the opposite side of the Earth?","opts":["The Sun pulls the water there","The water on the far side is pulled less than the Earth","The Moon''s gravity is stronger there","The Earth''s rotation stops the water"]},{"stem":"Why does the professor mention the Sun?","opts":["To show it is the main cause of tides","To explain that it also influences the tides, though less than the Moon","To argue that tides are not related to gravity","To describe the seasons"]},{"stem":"What can be inferred about spring tides?","opts":["They occur only in the spring","They are weaker than neap tides","They occur when the Sun, Moon, and Earth line up","They occur once a year"]}]}', '[3,1,1,2]', '["*what causes them* — приливы. A — не обсуждается; B — вращение — деталь; C — береговая линия не обсуждается","*the water is left behind*. A — Солнце действует слабее; C — гравитация слабее на дальней стороне; D — не упоминается","*The Sun also affects the tides, although less*. A — главная причина — Луна; C — гравитация — причина; D — сезоны не связаны","*at new moon and full moon … spring tides*; название не про сезон. A — не про сезон; B — они сильнее; D — не раз в год","Anyone who has spent time at the beach has seen the tides, the regular rise and fall of the sea. Today I''d like to explain what causes them. The main cause is the Moon. The Moon''s gravity pulls on the Earth, and because water can move freely, the ocean bulges toward the Moon. That creates a high tide on the side of the Earth facing it. Interestingly, there is also a second bulge on the opposite side of the planet. This happens because the Earth itself is pulled toward the Moon more strongly than the water on the far side is, so the water is left behind. As the Earth rotates, most coasts pass through two high tides and two low tides each day. The Sun also affects the tides, although less, because it is much farther away. When the Sun, Moon, and Earth line up, at new moon and full moon, their pulls combine, and we get unusually high tides called spring tides. When they form a right angle, the tides are weaker. These are called neap tides. Despite the name, spring tides have nothing to do with the season. Please remember that for the quiz on Friday."]', '["Main Idea","Factual","Purpose","Inference"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-B-015', 'L', 'lat', 'B', '{"kind":"TALK","audio":"audio/L/TALK-015.mp3","test":null,"qs":[{"stem":"What was the main advantage of Gutenberg''s printing press?","opts":["It made books more beautiful","It allowed books to be written in new languages","It made copying by hand unnecessary for scientists only","It made books faster and cheaper to produce"]},{"stem":"According to the professor, why did some leaders worry about printing?","opts":["Cheap books could spread dangerous ideas","Books were too expensive","Printers did not pay taxes","Readers could not understand the books"]},{"stem":"Why does the professor compare the printing press to the internet?","opts":["Both were invented in Germany","Both were controlled by governments","Both changed how fast information spreads","Both made books unnecessary"]},{"stem":"What does the professor suggest students do?","opts":["Memorize dates in the talk","Copy a page by hand","Think about who benefits from new technology","Write about the church''s role"]}]}', '[3,0,2,2]', '["*faster and much cheaper*. A — красота не упоминается; B — языки не упоминаются; C — ограничение по группе нет","*cheap books would spread dangerous ideas*. B — книги дешёвые; C — налоги не упоминаются; D — не упоминается","*both changed how quickly information moves*. A — не упоминается; B — не утверждается; D — не утверждается","*ask yourself who gained and who lost*. A — не просит; B — иллюстрация, не задание; D — не просит","Imagine copying an entire book by hand. Before the fifteenth century, that was how every book in Europe was made, and it could take months. Then, around fourteen fifty, a German craftsman named Johannes Gutenberg developed a printing press that used movable metal type. Individual letters could be arranged into a page, printed many times, and then rearranged for the next page. This made books faster and much cheaper to produce. The effects were enormous. In the fifty years after Gutenberg, millions of books were printed across Europe. Ideas spread faster than ever before. Scientists could share discoveries, and ordinary people began to read. Literacy rose slowly, but steadily. Not everyone welcomed the change, though. Some church leaders and rulers worried that cheap books would spread dangerous ideas, and they tried to control what could be printed. Still, it was impossible to stop. Historians often compare the printing press to the internet today, because both changed how quickly information moves. When you read about a revolution in communication, ask yourself who gained and who lost from the new technology."]', '["Main Idea","Factual","Purpose","Inference"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-B-018', 'L', 'lat', 'B', '{"kind":"TALK","audio":"audio/L/TALK-018.mp3","test":null,"qs":[{"stem":"What is the talk mainly about?","opts":["Why the sky looks blue","How sunsets are photographed","Why clouds are white","How the atmosphere is formed"]},{"stem":"According to the professor, why is the sky not violet?","opts":["The Sun emits less violet light and our eyes are less sensitive to it","Violet light is absorbed by the clouds","Violet light does not enter the atmosphere","Violet light is scattered less than red light"]},{"stem":"Why does the professor mention sunsets?","opts":["To prove that violet light is the strongest","To explain how clouds form","To compare day and night temperatures","To show how the distance light travels affects its color"]},{"stem":"What can be inferred about long wavelengths of light?","opts":["They cannot be seen by humans","They are scattered less by the atmosphere than short wavelengths","They are produced only at sunset","They are stronger than blue light"]}]}', '[0,0,3,1]', '["Рэлеевское рассеяние объясняет синий цвет. B — облака — на четверг; C — тема лекции; D — состав атмосферы лишь фон","*two reasons*: меньше фиолетового и глаза менее чувствительны. B — облака не упоминаются; C — входит; D — рассеивается больше","*sunlight travels through much more atmosphere*. A — не доказывает; B — облака — другая тема; C — температура не обсуждается","*short wavelengths… are scattered much more than long*. A — красный виден; C — не только на закате; D — не сравнивается по силе","Why is the sky blue? It''s a question children ask, and the answer is surprisingly interesting. Sunlight looks white, but it is actually a mixture of all colors, from red to violet. When sunlight enters the atmosphere, it collides with gas molecules, mostly nitrogen and oxygen. These molecules scatter the light in all directions. The key point is that short wavelengths, such as blue and violet, are scattered much more than long wavelengths, such as red and orange. This is called Rayleigh scattering, after the British physicist who explained it. As a result, blue light bounces around the sky and reaches your eyes from every direction. You might ask why the sky isn''t violet, since violet scatters even more than blue. There are two reasons. The Sun emits less violet light than blue, and our eyes are less sensitive to violet. At sunset, the sunlight travels through much more atmosphere to reach us. Most of the blue is scattered away along the way, which leaves the longer wavelengths, so we see red and orange. On Thursday, we''ll look at how the same principle explains why clouds are white."]', '["Main Idea","Factual","Purpose","Inference"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-B-019', 'L', 'lat', 'B', '{"kind":"TALK","audio":"audio/L/TALK-019.mp3","test":null,"qs":[{"stem":"What does the professor emphasize about the Silk Road?","opts":["It was built by a single empire","It was used only for silk","It was a network of routes rather than a single road","It was mainly a military route"]},{"stem":"According to the professor, how did most goods travel along the Silk Road?","opts":["By a single caravan","From merchant to merchant","On large ships","By government messengers"]},{"stem":"Why does the professor mention papermaking?","opts":["To show that China invented silk","To describe how books were produced","To give an example of a technology that spread along the routes","To explain why the plague spread"]},{"stem":"What does the professor imply about why overland trade declined?","opts":["The cities along the route disappeared","The plague ended trade completely","Silk lost its value","Sea routes became cheaper"]}]}', '[2,1,2,3]', '["*wasn''t one road. It was a network*. A — не упоминается; B — были и другие товары; D — не упоминается","*like a relay*. A — мало кто проезжал весь путь; C — морские маршруты позже; D — не упоминается","*technologies like papermaking moved westward*. A — шёлк — другое; B — производство книг не описано; D — чума — отдельно","*sea routes had become cheaper*. A — не говорится; B — не говорится; C — не говорится","When we think of ancient trade, we often picture the Silk Road. But the Silk Road wasn''t one road. It was a network of routes that stretched more than four thousand miles, connecting China with the Mediterranean from about the second century B.C. Few traders traveled the whole distance. Instead, goods passed from merchant to merchant, like a relay. Silk was the most famous product, but caravans also carried spices, metals, glass, and horses. Perhaps the most important thing that traveled, however, was not a product. It was ideas. Religions such as Buddhism spread from India into China along these routes, and technologies like papermaking moved westward. Cities along the way, such as Samarkand, grew wealthy as trading centers. The Silk Road also had a darker side. Diseases could spread along the same paths, and historians believe that the plague of the fourteenth century may have traveled this way. By the sixteenth century, sea routes had become cheaper, and the overland trade declined. For next class, please read the assigned chapter on the spread of Buddhism."]', '["Main Idea","Factual","Purpose","Inference"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-B-020', 'L', 'lat', 'B', '{"kind":"TALK","audio":"audio/L/TALK-020.mp3","test":null,"qs":[{"stem":"What is the lecture mainly about?","opts":["How prices are determined in a market","Why concert tickets are expensive","How sellers advertise products","Why shortages are harmful"]},{"stem":"According to the professor, what happens when the price is above the equilibrium price?","opts":["Demand suddenly rises","Sellers increase production","Some goods remain unsold","Buyers cannot find products"]},{"stem":"Why does the professor mention a new fashion?","opts":["To prove that supply never changes","To explain why prices fall","To show how a change in demand can change a price","To describe a typical shortage"]},{"stem":"What will students probably do before the next class?","opts":["Calculate an equilibrium price","Explain a recent change in the price of a product","Attend a concert","Write a report on shortages"]}]}', '[0,2,2,1]', '["Спрос, предложение и равновесная цена. B — концерт — пример; C — реклама не обсуждается; D — вред не обсуждается","*there are surpluses, and goods remain unsold*. A — спрос падает; B — сказано: цену снижают; D — это при низкой цене","*a new fashion makes a product popular, demand rises*. A — не утверждается; B — цена растёт; D — не описывает дефицит","*think of a product whose price changed*. A — не просит; C — не просит; D — не просит","Imagine that your favorite band announces a concert, and tickets cost thirty dollars. They sell out in minutes. Now imagine the same tickets sell for a hundred. Which situation tells us more about how markets work? Today''s topic is supply and demand. Demand is how much of a product people want to buy at a given price. In general, as the price rises, demand falls. Supply is how much sellers are willing to produce. As the price rises, supply usually rises, too, because selling becomes more profitable. The price where the two meet is called the equilibrium price. At that price, the amount buyers want equals the amount sellers offer. If the price is below it, there are shortages, and some buyers can''t get the product. If it is above it, there are surpluses, and goods remain unsold. Sellers then lower the price. Notice that prices rarely stay still for long. If a new fashion makes a product popular, demand rises, and the equilibrium price goes up. For next time, think of a product whose price changed recently, and be ready to explain why."]', '["Main Idea","Factual","Purpose","Inference"]', 0, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-002', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-002.mp3","test":"T1","qs":[{"stem":"What is the talk mainly about?","opts":["Why students forget what they read","How practicing recall helps people remember","Why practice tests are stressful","How to read a passage more quickly"]},{"stem":"How does the professor explain the testing effect?","opts":["By comparing two groups of students in a study","By describing her own experience as a student","By listing the parts of the brain involved","By defining memory in scientific terms"]},{"stem":"What does the professor imply about rereading?","opts":["It is useful only for short passages","It feels easier but is less effective","It is harder than taking a test","It should be avoided completely"]},{"stem":"What is the professor''s attitude toward students who prefer rereading?","opts":["She thinks their choice is a mistake","She believes it is the best method","She is unsure which method is better","She thinks it depends on the course"]}]}', '[1,0,1,0]', '["A — забывание лишь вводная тема; C — стресс не обсуждается; D — скорость чтения не упоминается","Описание исследования: одна группа перечитывала, другая сдавала практический тест. B, C, D — не упоминаются","*it feels harder (testing)… most students still prefer rereading*. A, D — не сказано/слишком сильно; C — противоположно","Маркер: *Honestly, I think that''s a mistake*. B, C, D — противоположно/не сказано","Last week, we talked about how people forget things. Today, I want to talk about a surprisingly simple way to fight forgetting. It''s called the testing effect. Here''s the basic idea: when you try to recall information from memory, you strengthen that memory more than when you simply read it again. In one well-known study, students read a short passage. One group then read it three more times. The other group read it once and then took a practice test, without looking back at the text. A week later, the students who had practiced recalling the passage remembered far more. Now, you might think the test group was just lucky, but the pattern has been repeated many times. So why does it work? Well, researchers think that struggling to remember forces the brain to rebuild the information, and that effort is what makes it stick. Of course, it feels harder, which is why, um, most students still prefer rereading. Honestly, I think that''s a mistake. Next time you study, close the book and quiz yourself first."]', '["Main Idea","Method","Inference","Attitude"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-004', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-004.mp3","test":"T1","qs":[{"stem":"What is the talk mainly about?","opts":["How honeybees communicate where food is","Why honeybees live in large groups","How honeybees build their hives","Which flowers honeybees prefer"]},{"stem":"According to the professor, what does the length of the waggle indicate?","opts":["The distance to the food","The direction of the food","The quality of the food","The type of flower the bee found"]},{"stem":"How did von Frisch test his idea?","opts":["By recording the sounds the bees made","By comparing bees from different countries","By moving food sources and seeing if bees could find them","By removing the sun''s light from the hive"]},{"stem":"What is the professor''s attitude toward the waggle dance?","opts":["She doubts that it carries information","She thinks it is too simple to study","She is impressed by what it shows about bees","She believes it is well understood already"]}]}', '[0,0,2,2]', '["B, C, D — не обсуждаются","*a longer waggle means a greater distance*. B — направление передаётся наклоном танца; C, D — не сказано","*He moved food sources to different places…*. A, B, D — не упоминаются","*What I find remarkable… one of the clearest examples*. A, D — противоположно/не сказано; B — противоположно","Let''s turn to a fascinating example of animal communication: the honeybee. When a worker bee finds a good source of food, say a field of flowers, she returns to the hive and performs what''s known as a waggle dance. The bee moves in a figure-eight pattern, and in the middle of the figure she shakes her body from side to side. Now, this isn''t random movement. The direction of the waggle run, relative to straight up on the honeycomb, tells the other bees the direction of the food in relation to the sun. And the length of the waggle tells them how far away it is: a longer waggle means a greater distance. The Austrian scientist Karl von Frisch spent years studying this behavior, and in 1973 he shared a Nobel Prize for his work. What I find remarkable is how he tested his idea. He moved food sources to different places and watched whether the bees at the hive could find them using only the information in the dance. They could, which was strong evidence that the dance carries real information. Of course, some scientists were skeptical at first, and it took many more experiments to convince them. Still, I think it''s one of the clearest examples we have of a small animal brain solving a complex problem."]', '["Main Idea","Factual","Method","Attitude"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-005', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-005.mp3","test":null,"qs":[{"stem":"What is the main point of the talk?","opts":["Concerts are a poor way to spend money","Managers should avoid developing new products","Most businesses fail because of poor sales","Money already spent should not drive future decisions"]},{"stem":"Why does the professor mention the concert ticket?","opts":["To show how expensive entertainment has become","To compare students with managers","To explain why bad weather affects business","To illustrate the sunk cost fallacy in an everyday situation"]},{"stem":"According to the professor, what should a decision be based on?","opts":["The money already invested","The opinions of other managers","Whether future benefits will outweigh future costs","How much effort has been spent so far"]},{"stem":"What does the professor imply about managers who stop a failing project?","opts":["They are often wrong about the product","They are afraid of taking risks","They may use resources more effectively","They do not care about past spending at all"]}]}', '[3,3,2,2]', '["A, B, C — не главная мысль","Пример вводит понятие *sunk cost fallacy*. A, B, C — не сказано","*whether future costs will be outweighed by future benefits*. A, D — это и есть ошибка; B — не сказано","*move their resources somewhere more useful*. A, B — не сказано; D — слишком сильно","Imagine you''ve bought a ticket to a concert for fifty dollars. On the night of the show, it''s snowing heavily, you''re tired, and you really don''t want to go. Do you go anyway? Many people say yes, because they''ve already paid. Economists call this the sunk cost fallacy. A sunk cost is money, time, or effort that''s already been spent and can''t be recovered. The fallacy is letting that past spending influence a decision about the future. Think about it: the fifty dollars is gone whether you attend or stay home. The only question that matters is, will going be worth it from now on? Businesses make the same mistake. A company may have spent millions developing a product, and when early sales are poor, managers keep investing, saying, \"We''ve come too far to quit.\" But the money already spent shouldn''t be part of the calculation. What matters is whether future costs will be outweighed by future benefits. Now, I''m not saying it''s easy. Quitting feels like admitting failure. But some of the best managers I''ve known are willing to say, \"Let''s stop here,\" and move their resources somewhere more useful. So the next time you''re tempted to continue just because you''ve already invested, ask yourself that one question about the future."]', '["Main Idea","Purpose","Factual","Inference"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-007', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-007.mp3","test":"T2","qs":[{"stem":"What is the talk mainly about?","opts":["Why medieval artists avoided realism","How architects influenced science","How linear perspective changed painting","The life of Brunelleschi"]},{"stem":"Why does the professor compare the two paintings at the beginning?","opts":["To explain the history of oil paints","To criticize older artists","To show the effect of linear perspective","To introduce the topic of architecture"]},{"stem":"According to the professor, who described the method in a book?","opts":["Brunelleschi","A medieval monk","Alberti","A modern scientist"]},{"stem":"What is the professor''s attitude toward the claim that perspective influenced early science?","opts":["He considers it completely false","He agrees with it entirely","He finds it interesting but does not fully accept it","He thinks it has not been studied"]}]}', '[2,2,2,2]', '["Тема — линейная перспектива и её влияние на живопись. A — реализм они не избегали намеренно — вопрос не об этом; B — наука — лишь упомянутая идея; D — биография не рассказывается","Сначала плоская картина, затем с глубиной — *What changed was … linear perspective*. A — масло не упоминается; B — критики нет; D — архитектор — деталь","*a writer named Leon Battista Alberti described the method in a book*. A — он разработал геометрию, но не писал книгу; B — не упоминается; D — не упоминается","*I wouldn''t go quite that far, but … worth thinking about*. A — слишком сильно; B — противоположно; D — не сказано","Look at this painting from the early fourteen hundreds, and then at one from the twelve hundreds. What''s the difference? In the older painting, figures look flat, and buildings seem to tilt in odd directions. In the newer one, the room seems to recede into the distance, like a real space. What changed was a technique called linear perspective. The basic idea is simple. In real life, parallel lines, such as the edges of a road, appear to meet at a single point on the horizon. Artists began to draw lines that way, and objects further away were made smaller. The architect Filippo Brunelleschi is usually credited with working out the geometry, and a writer named Leon Battista Alberti described the method in a book in the fourteen thirties. Now, here''s what I find interesting. Perspective didn''t just make paintings look more realistic. It changed how artists thought about their job. Instead of telling a story with symbols, they were now creating a window onto a believable world. Some historians even argue that it influenced early science, because both depended on careful observation and measurement. I wouldn''t go quite that far, but the connection is certainly worth thinking about. For Thursday, read the chapter on Alberti and note how he explains the method."]', '["Main Idea","Purpose","Factual","Attitude"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-009', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-009.mp3","test":"T2","qs":[{"stem":"What is the talk mainly about?","opts":["Why the Earth''s orbit is not circular","What actually causes the seasons","How the sun produces energy","Why winter is longer than summer"]},{"stem":"Why does the professor describe the flashlight demonstration?","opts":["To illustrate how angle affects the intensity of sunlight","To prove the Earth is closer to the sun in winter","To show how to measure the Earth''s tilt","To compare different kinds of lights"]},{"stem":"According to the professor, when is the Earth closest to the sun?","opts":["In late June","In the spring","In September","In early January"]},{"stem":"Why does the professor think the misconception is so common?","opts":["Textbooks often explain it incorrectly","Students do not study astronomy","Orbits are hard to measure","It fits people''s everyday experience with heat"]}]}', '[1,0,3,3]', '["Вопрос в начале и ответ: наклон оси. A — орбита — лишь довод; C — не обсуждается; D — не утверждается","*Same flashlight, same energy, different intensity*. B — говорит обратное; C — не измеряют; D — не сравнивают","*closest to the sun in early January*. A — не то время; B — не то время; C — не то время","*Probably because it matches our everyday experience*. A — не упоминается; B — не упоминается; C — не упоминается","Here''s a question I ask every year: why do we have seasons? Most students say it''s because the Earth is closer to the sun in summer and farther in winter. It sounds logical, but it''s wrong. In fact, the Earth is closest to the sun in early January, in the middle of winter for the Northern Hemisphere. The real cause is the tilt of the Earth''s axis, about twenty-three and a half degrees. Because of that tilt, during part of the year the Northern Hemisphere leans toward the sun, and sunlight hits it more directly. The rays are concentrated, and days are longer. Six months later, the hemisphere leans away, and the same amount of sunlight is spread over a larger area, so it feels cooler. Here''s an easy way to see this: shine a flashlight straight down on a table, and then at an angle. The straight beam makes a small, bright circle. The angled beam makes a bigger, dimmer oval. Same flashlight, same energy, different intensity. Why is this misconception so common? Probably because it matches our everyday experience that closer to a heat source means warmer. That''s why it''s useful to test our assumptions, even when they seem obvious."]', '["Main Idea","Purpose","Factual","Inference"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-011', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-011.mp3","test":"T3","qs":[{"stem":"What problem did railroads face before standard time?","opts":["Trains ran too slowly to follow a schedule","Passengers refused to buy tickets","Governments forbade trains from crossing borders","Local clocks in different towns did not agree"]},{"stem":"What does the professor say about the 1883 decision?","opts":["It was ordered by the government","It was made by railroad companies rather than by law","It was welcomed by all cities","It created six time zones"]},{"stem":"Why does the professor mention Indiana?","opts":["To show where the first time zone began","To explain why accidents were more frequent","To give an example of resistance to the change","To describe where standard time was invented"]},{"stem":"What does the professor imply about standard time?","opts":["It was unpopular for several decades","It spread because it was practical","It was mainly useful for farmers","It was based on the sun''s position"]}]}', '[3,1,2,1]', '["*Before railroads, every town set its clock by the sun*; расписания путались. A — скорость не проблема; B — билеты покупали; C — границы не упоминаются","*this was not a law. It was a private decision made by businesses*. A — закон принят в 1918; C — многие города сопротивлялись; D — сказано: четыре","*In Indiana, for instance, people argued…*. A — начало зоны не упоминается; B — аварии не связаны с Индианой; D — изобретение не там","*the convenience was too great to ignore*. A — принято в течение десятилетий; C — фермеры не упоминаются; D — время по солнцу — прежняя система","Imagine arriving at a train station in the eighteen-sixties and finding that its clock disagreed with the one in the next town. This was normal. Before railroads, every town set its clock by the sun, so noon happened at slightly different moments from place to place. That was fine when travel was slow. But trains changed everything. A schedule that listed arrival times in dozens of local times was nearly impossible to follow, and accidents became a real danger. Some railroads even printed several times on their tickets. The solution came in eighteen eighty-three, when North American railroad companies agreed to divide the continent into four standard time zones. Notice that this was not a law. It was a private decision made by businesses. Many cities resisted at first. In Indiana, for instance, people argued that they should not have to change their clocks to suit a railroad. Some called the day of the change the day of two noons, because clocks in many places were set back and noon arrived twice. Still, the convenience was too great to ignore. Within a few decades, standard time became the norm, and the government made it official in nineteen eighteen."]', '["Main Idea","Factual","Purpose","Inference"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-013', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-013.mp3","test":"T3","qs":[{"stem":"What is the main purpose of the talk?","opts":["To compare rivers and lakes","To describe how rocks are formed","To explain why the ocean is salty and stays at a stable level","To show why underwater volcanoes erupt"]},{"stem":"According to the professor, how does salt from rocks reach the ocean?","opts":["Waves break rocks along the coast","Salt falls from the atmosphere","Fish carry minerals from rivers","Rainwater carries minerals into rivers"]},{"stem":"Why does the professor mention evaporation?","opts":["To argue that the ocean is getting smaller","To explain why salt stays when water leaves","To show how rain forms","To describe how salt leaves the ocean"]},{"stem":"What can be inferred about enclosed lakes that have no outlet?","opts":["They receive less rainfall than oceans","They contain no minerals","Salt builds up in them because it cannot leave","They are older than oceans"]}]}', '[2,3,1,2]', '["Откуда соль и почему её уровень стабилен. A — реки — лишь деталь; B — образование пород лишь упомянуто; D — вулканы — небольшой источник","*Rain … carries minerals … into rivers*. A — волны не упоминаются; B — атмосфера не упоминается; C — рыбы не упоминаются","*water leaves … but the salt stays behind*. A — уменьшение не утверждается; C — образование дождя не обсуждается; D — соль остаётся, а не уходит","*enclosed lakes, which have no outlet, are far saltier*; баланс нарушен. A — осадки не сравниваются; B — минералы есть; D — возраст не упоминается","The oceans contain about thirty-five grams of salt in every liter of water, yet rivers, which keep pouring into the sea, taste fresh. So where did the salt come from, and why doesn''t the ocean get saltier each year? The salt comes mostly from rocks. Rain is slightly acidic, and as it falls on land, it slowly breaks down rocks and carries minerals, including sodium, into rivers. Over millions of years, these minerals have collected in the ocean. A smaller amount comes from underwater volcanoes and vents. Water, meanwhile, leaves the ocean through evaporation, but the salt stays behind. You might expect this to make the ocean saltier forever. Yet the salt level has remained fairly stable for a very long time. That is because salt is also removed. Some minerals combine with sediments and sink to the sea floor, and others become part of new rock. Scientists describe this as a balance, where the amount entering equals the amount leaving. A common mistake is to think the ocean is salty simply because the sea is old. Age matters, but balance matters more. This also explains why some enclosed lakes, which have no outlet, are far saltier than the ocean."]', '["Main Idea","Factual","Purpose","Inference"]', 1, 'pretest', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-016', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-016.mp3","test":null,"qs":[{"stem":"What is the lecture mainly about?","opts":["How air conditioners work","Why countryside areas are cooler in winter","How cities choose building materials","Why cities are warmer than surrounding areas and how to reduce this effect"]},{"stem":"According to the professor, why does the difference in temperature often peak after sunset?","opts":["Cars are used more in the evening","Trees stop releasing water vapor","Wind blows hardest after dark","Materials release absorbed heat slowly at night"]},{"stem":"Why does the professor mention white roofs?","opts":["To show that roofs cause the heat island","To explain how plants cool the air","To describe a problem with green roofs","To give an example of a way cities respond to heat"]},{"stem":"What does the professor imply about the solutions she describes?","opts":["They are too costly for most cities","They work best when used together","They have already solved the problem","They are only useful for elderly residents"]}]}', '[3,3,3,1]', '["Причины острова тепла и меры. A — кондиционеры — одна из причин; B — зима не обсуждается; C — материалы — причина, не тема","*absorb sunlight during the day and release the heat slowly at night*. A — не причина; B — транспирация — другая причина; C — ветер блокируется зданиями","*painting roofs white to reflect sunlight*. A — тёмные крыши — причина; B — про растения другое; C — проблем не называет","*None… perfect, but together they can lower the temperature*. A — стоимость не упоминается; C — проблема не решена; D — не только для пожилых","If you''ve ever noticed that a city feels hotter than the countryside around it, you''ve experienced an urban heat island. On a summer evening, a city can be several degrees warmer than nearby rural areas, and the difference is often largest after sunset. Why does this happen? First, materials like asphalt, concrete, and dark roofs absorb sunlight during the day and release the heat slowly at night. Second, cities have fewer plants and trees. Vegetation cools the air by releasing water vapor, a process called transpiration. Third, tall buildings block the wind and trap heat between them, and air conditioners, cars, and factories all add heat of their own. The consequences are more than just discomfort. Hotter nights increase energy use, worsen air pollution, and can be dangerous for elderly residents. So how can cities respond? Some are painting roofs white to reflect sunlight, while others plant trees along streets or build parks. A few even install green roofs, which are covered with vegetation. None of these solutions is perfect, but together they can lower the temperature noticeably. Please read chapter nine before our next meeting."]', '["Main Idea","Factual","Purpose","Inference"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-017', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-017.mp3","test":null,"qs":[{"stem":"What is the talk mainly about?","opts":["The placebo effect and how it affects medical research","How painkillers work in the brain","Why patients dislike doctors","How to design a medicine"]},{"stem":"According to the professor, what is one explanation for the placebo effect?","opts":["Sugar pills contain weak medicine","Doctors choose healthier patients","Patients'' expectations may trigger natural pain relief","Patients take larger doses"]},{"stem":"Why does the professor mention a double-blind trial?","opts":["To show that placebos are harmful","To explain how scientists reduce bias in testing medicines","To argue that medicines are unnecessary","To describe how patients are chosen"]},{"stem":"What does the professor imply about the placebo effect?","opts":["It is stronger than most medicines","It works only on headaches","It is a real experience, not just imagination","It cannot be studied"]}]}', '[0,2,1,2]', '["Плацебо и его влияние на испытания. B — механизм лишь пример; C — не упоминается; D — не тема","*your brain may actually release natural chemicals*. A — нет активных веществ; B — не упоминается; D — не упоминается","*neither the patients nor the doctors know*. A — вред не обсуждается; C — не утверждается; D — отбор не обсуждается","*Patients really do feel better*. A — не утверждается; B — только пример; D — изучают","Imagine two groups of patients with the same headache. One group receives a real painkiller, and the other receives a sugar pill. Surprisingly, many in the second group report feeling better. This is the placebo effect, and it has puzzled researchers for decades. A placebo has no active ingredient, so why does it work? One explanation is expectation. If you believe a treatment will help, your brain may actually release natural chemicals that reduce pain. Another factor is the ritual of treatment, such as seeing a doctor and taking a pill. Researchers have even found that bigger pills, or ones with brand names, produce stronger effects. Because of the placebo effect, scientists who test new medicines must be careful. They usually compare the new drug with a placebo, and neither the patients nor the doctors know who got which. This design is called a double-blind trial. A medicine is considered effective only if it works better than the placebo. Notice that this doesn''t mean the placebo effect is imaginary. Patients really do feel better. The question is whether the medicine adds something beyond that."]', '["Main Idea","Factual","Method","Attitude"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-021', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-021.mp3","test":null,"qs":[{"stem":"What is the main point of the lecture?","opts":["Dreams predict future events","Sleep plays an active role in memory","Students should study less","Memory is not affected by sleep"]},{"stem":"According to the professor, which type of sleep may help with skills and creative problem solving?","opts":["Deep sleep","REM sleep","Daytime naps","Light sleep before waking"]},{"stem":"Why does the professor describe the study with two groups?","opts":["To provide evidence that sleep improves memory","To show that word pairs are easy","To demonstrate the dangers of cramming","To compare morning and evening learning"]},{"stem":"What does the professor imply about staying up all night before an exam?","opts":["It always leads to failure","It is useful only for facts","It is usually not an efficient way to prepare","It is the best way to memorize"]}]}', '[1,1,0,2]', '["*during sleep, the brain is busy sorting memories*. A — не утверждается; C — не призывает; D — противоположно","*the dreaming stage, known as REM sleep*. A — глубокий — для фактов; C — не упоминается; D — не упоминается","*the group that slept remembered considerably more*. B — лёгкость пар не обсуждается; C — цель — доказать пользу сна; D — утро/вечер не сравниваются","*cramming without sleep wastes much of the effort*. A — «always» слишком сильно; B — не утверждается; D — противоположно","We spend roughly a third of our lives asleep, yet for a long time scientists considered sleep a passive state. Research now suggests the opposite: during sleep, the brain is busy sorting memories. The process is called consolidation. When you learn something new, such as a list of words, the information is fragile. During sleep, your brain replays recent experiences and strengthens the useful connections. Different stages seem to matter for different kinds of memory. Deep sleep appears to help with facts, while the dreaming stage, known as REM sleep, may help with skills and creative problem solving. One famous study asked two groups to learn a set of word pairs. One group slept afterward, and the other stayed awake. When tested twelve hours later, the group that slept remembered considerably more. Of course, this doesn''t mean all-night cramming is useless. It means that cramming without sleep wastes much of the effort. In other words, sleep is not time taken from studying. It is part of studying. Consider that the next time you are tempted to stay up all night before an exam."]', '["Main Idea","Factual","Method","Attitude"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-022', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-022.mp3","test":null,"qs":[{"stem":"What is the lecture mainly about?","opts":["Why and how cities grew during the Industrial Revolution","How farming methods changed in England","Why cholera spread across Europe","How governments built sewers"]},{"stem":"According to the professor, why did fewer people need to work on farms?","opts":["Farming had improved","Factories needed more space","Farms were taken by the government","Diseases killed many farmers"]},{"stem":"Why does the professor mention life expectancy?","opts":["To show that rural life was dangerous","To illustrate the poor living conditions in industrial cities","To argue that reforms were unnecessary","To explain why people left cities"]},{"stem":"What is the professor''s attitude toward the Industrial Revolution?","opts":["She believes it was entirely positive","She thinks it harmed all workers","She considers it unimportant","She sees both benefits and costs"]}]}', '[0,0,1,3]', '["Урбанизация как следствие промышленной революции. B — фермерство — одна из причин; C — болезнь — следствие; D — реформы — часть темы","*improvements in farming meant that fewer workers were needed*. B — не упоминается; C — не упоминается; D — не упоминается","*Life expectancy in industrial cities was often lower*. A — сельская жизнь не опасна; C — реформы были; D — люди приходили в города","*enormous wealth, but also real suffering*. A — только плюсы — нет; B — не все вредило; C — важно","In seventeen-fifty, about one in six people in England lived in a town. By nineteen hundred, it was three in four. This movement of people from the countryside to cities, called urbanization, was one of the major consequences of the Industrial Revolution. Why did it happen? Factories needed workers in large numbers, and they were built near rivers and coal, which meant that towns grew quickly around them. Meanwhile, improvements in farming meant that fewer workers were needed on the land. Cities offered work, but their problems were severe. Housing was crowded and cheap, clean water was scarce, and diseases such as cholera spread rapidly. Life expectancy in industrial cities was often lower than in rural areas. Eventually, reformers pushed governments to build sewers, supply clean water, and regulate factories. These changes did not happen overnight. They took decades, and they were often resisted by factory owners. So, when we speak of progress, remember that the Industrial Revolution produced enormous wealth, but also real suffering. Historians still debate whether ordinary workers were better off in the short term."]', '["Main Idea","Factual","Purpose","Attitude"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
INSERT INTO items (id, section, task, level, body, key, explain, qtypes, b, status, created_at, updated_at) VALUES ('L-TALK-C-023', 'L', 'lat', 'C', '{"kind":"TALK","audio":"audio/L/TALK-023.mp3","test":null,"qs":[{"stem":"What is the lecture mainly about?","opts":["How immigrants find jobs","How grammar is taught in schools","Why accents are difficult to understand","Whether there is an ideal age for learning a language"]},{"stem":"Why does the professor say the case of Genie is hard to interpret?","opts":["She learned grammar too quickly","Her isolation involved other harmful factors","She was not given any help","She was too old to be studied"]},{"stem":"How did the studies of immigrants support the idea of a critical period?","opts":["Those who arrived as young children reached native-like grammar","Those who arrived later learned faster","All immigrants kept strong accents","The length of residence predicted success"]},{"stem":"What can be inferred about adult learners?","opts":["They cannot learn grammar","They learn faster than children","They never lose their accents","They can become fluent, though they may use different strategies"]}]}', '[3,1,0,3]', '["Критический/сензитивный период. A — работа не обсуждается; B — преподавание не обсуждается; C — акценты — лишь деталь","*her isolation also involved severe neglect*. A — она не выучила; C — помощь была; D — возраст не причина","*arrived … as young children reached native-like grammar*. B — противоположно; C — не только акценты; D — «regardless of how many years»","*Adults can still become fluent*. A — противоречит; B — не утверждается; C — «rarely» не «never»","Why do young children learn languages so easily, while adults often struggle? Some researchers believe in a critical period, a window of time in early life when the brain is especially open to learning language. The idea gained attention from the case of Genie, a girl discovered in nineteen seventy after being isolated from other people for years. Despite intensive help, she never mastered grammar, which suggested that language must be acquired early. However, the case is hard to interpret, because her isolation also involved severe neglect, which can harm development in many ways. More reliable evidence comes from immigrants. Studies found that people who arrived in a new country as young children reached native-like grammar, while those who arrived after puberty usually did not, regardless of how many years they had lived there. But notice that the decline seems gradual, not sudden, which is why many researchers now prefer the term sensitive period. Adults can still become fluent. They simply tend to rely on different strategies, such as memorizing rules, and they rarely lose their accent completely."]', '["Main Idea","Factual","Method","Inference"]', 1, 'active', 1793553157228, 1793553157228)
  ON CONFLICT(id) DO UPDATE SET task = excluded.task, level = excluded.level, body = excluded.body, key = excluded.key, explain = excluded.explain, qtypes = excluded.qtypes, status = excluded.status, updated_at = excluded.updated_at;
